window.HARDTRP.receive("226349",[[226350,"2026-09-20T10:58:52",9,"Начало темы.\n\n@Professor_3M653 — Дм этой темы.",226349,null],[226360,"2026-09-20T11:24:49",36,"@lady_godzilla, @Az095as0, @dethchinski",226349,null],[226361,"2026-09-20T11:24:59",36,"Когда сможете играть?",226349,null],[226362,"2026-09-20T11:27:25",64,"В понедельник, среду, пятницу считай свободен с 12:00, в другие дни с 18:00, в выходные занят с 14:00 до 18:00\n\nДумайте",226361,null],[226383,"2026-09-20T11:48:09",36,"В дороге значит буду вести, с 18:00\nИ мб пропаду по пути из за Беспилотников",226362,null],[226388,"2026-09-20T11:49:42",64,"А точно сегодня?",226383,null],[226389,"2026-09-20T11:51:45",36,"Точно сегодня буду вести, завтра буду сильно занята",226388,null],[226390,"2026-09-20T11:52:55",36,"📅 Расписание на Понедельник, 21.09.2026\n🟢 Неделя: знаменатель\n\n1 пара (08:10–09:45)\n┣ 📌 Лекция\n┃ 📖 Разработка инженерной документации\n┃ 👤 Акинина Н.В.\n┃ 🚪 448 C\n➖➖➖➖➖\n2 пара (09:55–11:30)\n┣ 📌 Лабораторная\n┃ 📖 Физика\n┃ 👤 Иваников А.С.\n┃ 🚪 353 C\n➖➖➖➖➖\n3 пара (11:40–13:15)\n┣ 📌 Лекция\n┃ 📖 Введение в профессиональную деятельность\n┃ 👤 Тарасов А.С.\n┃ 🚪 337 C\n➖➖➖➖➖\n4 пара (13:35–15:10)\n┣ 📌 Лекция\n┃ 📖 Информатика\n┃ 👤 Орехво Д.О.\n┃ 🚪 405 C\n➖➖➖➖➖",226349,null],[226391,"2026-09-20T11:53:11",36,"Расписание на завтра, а потом после лекций мероприятие",226390,null],[226392,"2026-09-20T11:53:20",36,"Так что либо сегодня, либо во вторник",226349,null],[226413,"2026-09-20T12:19:10",64,"Крутяк",226392,null],[226414,"2026-09-20T12:19:38",64,"Вообще ладно похуй, могу по кд играть, там в целом доступ будет к игре так что нормас",226362,null],[226415,"2026-09-20T12:19:44",64,"Как остальным удобно соберётесь",226349,null],[226535,"2026-09-20T14:06:33",36,"@lady_godzilla, @Az095as0",226415,null],[226536,"2026-09-20T14:06:57",44,"О искал это тему . Блять , нахуй мне расписание своей пары",226390,null],[226540,"2026-09-20T14:07:21",36,"Это мое расписание",226536,null],[226594,"2026-09-20T14:21:40",22,"будни с 09. до 18.00 точно свободна, в другое время и дни частично",226361,null],[226732,"2026-09-20T15:00:14",44,"Когда я  захочу  . Но обычно это всегда",226361,null],[226733,"2026-09-20T15:00:53",36,"Ну и отлично",226732,null],[227081,"2026-09-20T18:49:20",36,"Я так понимаю игра переносится на вторник?\n\n@lady_godzilla, @Az095as0, @dethchinski",226349,null],[227135,"2026-09-20T19:11:40",64,"Походу",227081,null],[227278,"2026-09-20T20:31:25",64,"А во сколько",227081,null],[227319,"2026-09-20T20:48:42",36,"Могу с 11:40 два часика, потом перекур тоже двух часовой и вновь играть",227278,null],[228056,"2026-09-21T14:16:58",36,"Можете повторно скинуть ссылки на ваших персонажей?\n\n@lady_godzilla, @Az095as0, @dethchinski, @Illidayn",226349,null],[228057,"2026-09-21T14:17:36",22,"https://t.me/c/3239766844/6097/6099",228056,null],[228061,"2026-09-21T14:18:19",36,"Охует! Не бард!\nЯ думала у нас тут три барда",228057,null],[228065,"2026-09-21T14:20:17",64,"https://t.me/c/3239766844/939",228056,null],[228070,"2026-09-21T14:21:18",48,"https://t.me/c/3239766844/8879/8901",228056,null],[228072,"2026-09-21T14:22:02",36,"А чо не продашь латы?",228065,null],[228076,"2026-09-21T14:23:01",22,"Она с предой артист😁",228061,null],[228081,"2026-09-21T14:24:17",64,"За 450 всего?",228072,null],[228082,"2026-09-21T14:24:39",64,"Может найду применение какое",228081,null],[228084,"2026-09-21T14:24:55",64,"Да и у меня Грейх после смерти одного из персов пойдёт ебла рвать, а ему латы под стать",226349,null],[228085,"2026-09-21T14:25:02",64,"Надо думать",228084,null],[228097,"2026-09-21T14:30:51",44,"Шлуха \nhttps://t.me/c/3239766844/2971",228056,null],[228099,"2026-09-21T14:31:40",36,"Ясн",228076,null],[228101,"2026-09-21T14:31:48",36,"Поторгуйся",228081,null],[228102,"2026-09-21T14:31:58",36,"А кста, сбавь кд с 18 на 16",228081,null],[228103,"2026-09-21T14:32:02",36,"Типо они старые",228102,null],[228104,"2026-09-21T14:32:08",36,"Я тогда не думала об этой хуйне",226349,null],[228106,"2026-09-21T14:32:35",36,"С 4 попытки поняла преду",228070,null],[228109,"2026-09-21T14:32:52",48,":3",228106,null],[228111,"2026-09-21T14:33:06",36,"Преду в лс скинешь, в анкете не вижу",228097,null],[228114,"2026-09-21T14:33:18",64,"Та все уже",228102,null],[228218,"2026-09-21T15:02:46",36,"Черти, у меня очень скучная пара\n\nПредлагаю играть\n@lady_godzilla, @Az095as0, @dethchinski, @Illidayn",226349,null],[228221,"2026-09-21T15:04:17",48,"//доходяга готов к клоунаде",228218,null],[228224,"2026-09-21T15:04:41",64,"У меня игра щас ищет",228218,null],[228225,"2026-09-21T15:04:43",64,"Идёт",226349,null],[228226,"2026-09-21T15:04:47",64,"Там файт на файте",226349,null],[228227,"2026-09-21T15:04:51",36,"Жаль",228226,null],[229984,"2026-09-22T13:48:36",36,"Прикиньте у меня все готово\nКроме реплик",226349,null],[229985,"2026-09-22T13:48:45",36,"Записанных",229984,null],[229990,"2026-09-22T14:02:12",36,"Когда играть сможете? Сегодня\n\n@lady_godzilla, @Az095as0, @dethchinski, @Illidayn",226349,null],[229994,"2026-09-22T14:03:11",48,"Ну до 22-23 по мск точно",229990,null],[229995,"2026-09-22T14:03:36",36,"Я предлагаю через два часа",226349,null],[229996,"2026-09-22T14:03:50",36,"Мб час",229995,null],[230003,"2026-09-22T14:06:55",64,"Та хоть щас, но переодически пропадать буду",229990,null],[230004,"2026-09-22T14:07:10",64,"И через где то полтора часа буду занят на пол часа",226349,null],[230015,"2026-09-22T14:12:32",22,"Я свободна до 18.00\n\nНу можем попробовать начать. Если я в ваш график влиться не смогу, то ливну просто",229990,null],[230017,"2026-09-22T14:12:43",44,"// для тебя всегда , потому что иза вашей порнуги меня нахуй послали",229990,null],[230019,"2026-09-22T14:13:54",48,"Нмхуя себе подруга",230017,null],[230041,"2026-09-22T14:23:42",36,"//прикол в том, что свою я удалила",230017,null],[230078,"2026-09-22T14:37:45",36,"//ну.... \nВот такая хуйня собачка",226349,null],[230079,"2026-09-22T14:37:54",36,"//вот такая собахуйнячка",226349,null],[230080,"2026-09-22T14:38:34",36,"//вот такая собаня хуйячка",226349,null],[230084,"2026-09-22T14:39:35",36,"Ладно, начнём",226349,null],[230115,"2026-09-22T14:43:50",36,"Увидев и прочитав объявление вы возможно пожимаете плечами, возможно заинтересовываетесь этим, но на следующее утро в своей сумке вы находите билеты в этот самый цирк, а на них места и время \"После удара первого колокола\".\n\nДругие кому было пофиг х2 просто выкинули билет. Вы же приняли его, несмотря на то, что кто-то из вас мог быть не заинтересован, но удивлен магическим трюком.\n\nПочти в полдень вы приходите на назначенное место. Это была заброшенная площадь, где уже никто не ходит, но она была достаточно большой для шатра, которого... Вы тут не наблюдали, может перепутали даты?",226349,null],[230118,"2026-09-22T14:44:11",36,"// @Az095as0 \n@lady_godzilla \n@Illidayn \n@dethchinski",230115,null],[230127,"2026-09-22T14:49:32",22,"- Ну вот, опять я адрес перепутала.\n\nАаракокра заозиралась по сторонам, сверяя адрес на билете и пытаясь сориентироваться на местности.",226349,null],[230128,"2026-09-22T14:50:08",36,"//Ооооо!!! Спасибо что ответила на мой пост",230127,null],[230130,"2026-09-22T14:50:13",48,"Сэдрик стоял напротив заброшенной площади во весь рост. Он медленно но с интересом проходился своим взглядом из под тьмы капюшона по этой местности. Ему не было  ново видеть подобное. Но ему было интересно что никто не готовился к представлению. Иногда он оьращац свою голову на дам рядом. Ему был интересен их вид, он предполагал в своей голове их мотивы, и все же он был спокоен все это время, не содрогаясь.",230115,null],[230131,"2026-09-22T14:50:23",36,"//прощён",230130,null],[230145,"2026-09-22T14:53:34",36,"// @Az095as0 \n@dethchinski \nВас ток ждём",226349,null],[230151,"2026-09-22T14:54:58",36,"//вот почему у мен всегда вечно проблемы, со сбором игроков...",226349,null],[230158,"2026-09-22T14:56:36",64,"Я",226349,null],[230162,"2026-09-22T14:57:03",36,"//пост пиши",230158,null],[230166,"2026-09-22T14:57:34",48,"//йца",226349,null],[230183,"2026-09-22T15:00:30",64,"Приходя на место чуть позже остальных, Вельдьен стряхивает пылинки с своей одежды, а позже осматривается и несколько насмешливо говорит тише, про себя \n—Пх.. магический цирк удивляет ещё до начала.. \n кажется она о чем то задумалась, а чуть позже осмотрелась, замечая остальных",230115,null],[230184,"2026-09-22T15:00:38",64,"//такая цаца",226349,null],[230187,"2026-09-22T15:00:49",48,"//ля какая",230184,null],[230188,"2026-09-22T15:00:51",64,"//ща, минуты 2-1.5",226349,null],[230190,"2026-09-22T15:01:34",36,"// @Illidayn \n@lady_godzilla \n@dethchinski \nВы пока втроём социалку обыграйте",226349,null],[230194,"2026-09-22T15:02:01",48,"//о",226349,null],[230196,"2026-09-22T15:02:04",36,"//оно живое!",226349,null],[230204,"2026-09-22T15:03:28",44,"||| а я лег спать . ладно пиеты , типо такие ?",226349,null],[230207,"2026-09-22T15:03:43",36,"//.... Формат да, надпись нет",230205,null],[230210,"2026-09-22T15:04:02",36,"//шутко\nБилеты на самолёт видел? Такие же",230207,null],[230211,"2026-09-22T15:04:13",36,"//не бумажные, картонные",230210,null],[230214,"2026-09-22T15:04:40",36,"//в вашем случае у них еще цвета переливаются и картинка движется иногда",230211,null],[230216,"2026-09-22T15:05:15",22,"- О, привет! Я Вакс. Вы тоже на мероприятие? Но мне кажется,  что адрес перепутан..",226349,null],[230219,"2026-09-22T15:08:17",64,"Вельдьен медленно и грациозно подходит к нему, аккуратно виляя хвостом из стороны в сторону. Её взгляд отведен чуть в сторону, в прочем, начиная диалог, своим нежным и спокойным, несколько даже умиротворяющим голосом, Вельдьен переводит взгляд на него \n—Ох, вы тоже пришли по объявлению? Небольшая пауза  —Я Вельдьен, рада познакомиться, с.. Вас не затруднит поведать ваше имя?",230130,null],[230224,"2026-09-22T15:09:45",44,"// ага  как я и думал , такие . ладно время пост написать . а вообще почему это называется так если пост это отказ от еды по какойто регизной хуйни .\n*  ШЛЮХА  Астольфо приходит на место встречи . он сразуже замечает чертей , дед инсайт и какой-то  тип  . пиздец . подума астольфо , но кого он не ебал . *\n--- здравствуйте , как я понимаю вы участники цирка или вы тоже получили билеты ?\n* астольфо сделал такие вовод иза того что , только  такие уроды могут быть  в цирк уродов *",230205,null],[230247,"2026-09-22T15:12:40",48,"- Мм..\n\nТаинственный мужчина(?) медленно разворачивается на даму. Лица Сэдрика(?) не видно, но Вельдьен чувствует на себе его невидимый взгляд.\n\n- ..Сэдрик, и..мне тоже приятно быть с вами знакомым.",230219,null],[230255,"2026-09-22T15:13:28",44,"// точно арт скинуть , чтобы вы поняли что тут не только вы уроды .*",230224,null],[230257,"2026-09-22T15:14:03",64,"//Что тут только мы не уроды* ну по крайней мере за Вельдьен",230255,null],[230258,"2026-09-22T15:14:06",36,"//только появился, а уже всех унизил",230224,null],[230259,"2026-09-22T15:14:08",48,"Потом он медленно обернулся на проститута, и тот тоже почувствовал его взгляд на себе\n\n- Я лишь зритель.",230224,null],[230260,"2026-09-22T15:14:35",48,"//назгул слишком неопытный чтобы понять что его унижают",230258,null],[230268,"2026-09-22T15:16:04",48,"//ААААААаа..это парень",230266,null],[230269,"2026-09-22T15:16:07",36,"//он не урод..",230266,null],[230271,"2026-09-22T15:16:20",44,"// к стати у меня есть версия без одежды. Но я не хочу опять пойти нахуй",230266,null],[230273,"2026-09-22T15:16:29",64,"Ну на неё оборачивается, но сильно от предыдущего собеседника не отходит, говорит чуть более бегло \n—Здравствуй, Вакс. Я Вельдьен. небольшая пауза —цирк магический, кажется нужно подождать",230216,null],[230276,"2026-09-22T15:16:44",36,"//у меня есть версия где его ебут",230271,null],[230277,"2026-09-22T15:16:56",64,"Кошмар конкуренты//",230266,null],[230279,"2026-09-22T15:17:08",64,"//через сколько партий",230276,null],[230282,"2026-09-22T15:17:53",48,"- Магический цирк..\n\nОн наклонил голову вправо, смотря..да непонятно куда он смотрит. \n\n- Какое интересно действо..Цирк, по вашему, явится из воздуха?",230273,null],[230284,"2026-09-22T15:18:34",48,"// 🙏😏",230276,null],[230286,"2026-09-22T15:19:31",64,"На пару градусов наклоняет голову и более заинтересованным тоном \n—А ты как думаешь?\n\n// @Professor_3M653 а колоколчики бились уже?",230282,null],[230288,"2026-09-22T15:21:23",44,"// к стати, дк , у меня есть книга который я могу выбрать Залкинание  барда или чародей раз в день . Так что я выбрал заклинание маскировка.",226349,null],[230289,"2026-09-22T15:21:34",48,"// смотря о каких колокольчиках речь\n\n‐ Я еще с таким не сталкивался. Я видел людей которые могут исчезнуть по своему желанию, но чтобы целый..\n\nОн на какое то время взял паузу. Пытается вспомнить как называется та большая палатка..\n\n-..шатер..",230286,null],[230290,"2026-09-22T15:22:25",36,"Вы слышите как стрелки часов, на старой, но всё еще работающей башне с глухим гулом двигаются на одну минуту вправо",230282,null],[230291,"2026-09-22T15:23:09",36,"//будешь всем говорить, что ты не шлюха? А потом выебешь в подворотне?",230288,null],[230294,"2026-09-22T15:23:51",36,"// @lady_godzilla \nМы тебя не запугали? А то молчишь",226349,null],[230295,"2026-09-22T15:24:06",36,"//пока не скажу обратного сцена не меняется",230286,null],[230296,"2026-09-22T15:25:23",64,"—Ну... Знаешь.. Небольшая пауза и чуть более затяжно  —Все когда-нибудь случается впервые\nОтвечает Вельдьен, поправляя свою прядь волос",230289,null],[230298,"2026-09-22T15:25:48",48,"Сэдрик глядит на часы и спрашивает себя, сколько осталось минут до полудня",230290,null],[230300,"2026-09-22T15:26:13",36,"\"Минута\", слышит он свой голос в ответ, в голове",230298,null],[230303,"2026-09-22T15:26:37",64,"Сошел с умов",230300,null],[230313,"2026-09-22T15:28:39",48,"Сэдрик решает пройти чуть вперед, буквально на два шага.\n\n- Еще минута, я полагаю",226349,null],[230324,"2026-09-22T15:31:51",22,"- Отлично. А вы часто посещаете похожие мероприятия?",230273,null],[230325,"2026-09-22T15:32:32",64,"—Впервые\nпожала плечами",230324,null],[230326,"2026-09-22T15:33:15",22,"- Ну тогда будем ждать.\n\nВакс села на наименее разрушенный обломок в ожидании.",226349,null],[230327,"2026-09-22T15:33:31",48,"- Ни разу до этого не встречался с таким. Очень, очень интригующе..",226349,null],[230329,"2026-09-22T15:35:09",64,"ну в ожидании Вельдьен достаёт флейту из кости и начинает наигрывать успокаивающую, но ритмичную мелодию",226349,null],[230334,"2026-09-22T15:37:37",64,"// @Professor_3M653 у меня есть ещё минут 20?",226349,null],[230336,"2026-09-22T15:38:11",36,"Пока вы ходили расслабленно к вам со спины подошёл джентельмен в шляпе. Который осмотрел вас оценивающим взглядом, а после вежливо кашлянул в кулак\n\n- Будьте любезны, отойдите в сторону",226349,null],[230337,"2026-09-22T15:38:16",48,"Сэдрик встал в такой же ступор как и до этого. Он стал в уме отсчитывать секунды",226349,null],[230340,"2026-09-22T15:39:04",36,"//уважения к нему, ибо я хз чо это за перс, он из пинты",230336,null],[230349,"2026-09-22T15:40:09",64,"ну прекращает мелодию, оборачиваясь на фигуру \n—Здравствуйте, хорошо.. пауза, отходит в сторону —Вы не знаете когда будет начало?",230336,null],[230350,"2026-09-22T15:40:34",48,"Сэдрик медленно обернулся на мужчину. Его глаз не видно, но уже понятно куда он обращен. \n\n- Извините..а вы артист? \n\nЗада вэтот вопрос, он покорно отходит, не снимая глаз с шляпника.",230336,null],[230353,"2026-09-22T15:41:07",36,"// @Az095as0 \n@lady_godzilla",230336,null],[230355,"2026-09-22T15:41:30",22,"- Ой. Прошу прощения. А вы тоже на представление?\n\nВакс спрыгнула со своего места и посмотрела на незнакомца, по-птичьему наклонив голову.",230336,null],[230360,"2026-09-22T15:42:39",22,"//буду отвечать дольше, но больше. Продолжайте играть, я постфактум опишу реакцию на все. \nМне по работе нужно проверить хреновые чертежи и объяснить ребятам что они не правы.",226349,null],[230362,"2026-09-22T15:43:06",36,"//она отошла же?",230355,null],[230364,"2026-09-22T15:43:30",64,"//я походу отойду на минут 15-20 пока домой еду",226349,null],[230369,"2026-09-22T15:44:28",36,"//ну... Тогда последнюю реакцию и перекур",230364,null],[230371,"2026-09-22T15:45:01",64,"Э//",230369,null],[230372,"2026-09-22T15:45:02",44,"* астольфо увидел секси  велика  . Он страх уже  от отошёл  по  его просьбы .  *\n--- да беспраблем . \n* Астольфо осматривает его понимает , а что он не плох . Но чайка подсказывает что с ним не так .*",230336,null],[230373,"2026-09-22T15:45:09",44,"/r 1d20+2+2",230372,null],[230376,"2026-09-22T15:45:18",44,"// проницательность.",230374,null],[230377,"2026-09-22T15:45:45",64,"//мастер начальник ладно",230369,null],[230379,"2026-09-22T15:47:17",36,"Это вполне обычный подозрительный джентельмен в шляпе и с карманными часами, который пришел как и вы, но не на представление, а с поручением. Который он судя по всему выполнил",230374,null],[230391,"2026-09-22T15:52:50",36,"Джентельмен осматривает вас, затем достает карманные часы и отвечает \"Скоро\".\n\nПосле чего убирает их переводя взгляд на призрака и птицу\n\n- Нет, я не связан с цирком...\n\nПосле чего он поворачивается вправо и уходит, в вы слышите как стрелка с гулом передвигается еще на одну минуту вправо. Вы машинально поворачиваете голову на этот звук и видите как колокол начал движение...\n\n\"ДОН!\"\n\nРазнёсся звон колокола на всю площадь и впереди вас, вы услышали веселую музыку. Когда посмотрели на источник, то увидели шатёр цирковой. И вход в него.\n\nРядом с входом стоял манекен в костюме фокусника и протягивал руку вперед, прося вас билет, фразой \"Give me five coins\"\n\nЗатем глухой удар по его затылку чем то разноцветным, что вылезло из шатра на мгновение и он стал говорить:\n\"Give me a ticket\"",226349,null],[230393,"2026-09-22T15:53:02",36,"//через проход нельзя было увидеть что внутри",230391,null],[230394,"2026-09-22T15:53:20",36,"Когда вы осмотрелись в поисках джентльмена, то вы его не обнаружили",230391,null],[230397,"2026-09-22T15:55:37",44,"// а кто будем меня ебать :(",230394,null],[230399,"2026-09-22T15:59:00",44,"// иди нахуй , я английский не знаю . Ладно , я понял что этот чел на отсылку из фнафа . \n* Астольфо , видео какие-то челиков . Походу это они просят билеты .  Астольфо, достает билет и протягивает ему *\n---- вот , билет . Так что я могу пройти ?",230391,null],[230400,"2026-09-22T16:00:01",36,"Манекен сжимает в пальцах билет и срывает край, после чего протягивает его тебе обратно",230399,null],[230401,"2026-09-22T16:00:09",48,"Не связан с цирком? Сэдрик задумался об этом страннейшем совпадении на минуту, но потом решает пока не нагружать себя этим мужиком и встает около входа, ожидая пока дамы и проститут пройдут внутрь чтобы зайти в последнюю очередь.",226349,null],[230411,"2026-09-22T16:02:06",44,"* астольфо берет проверенный билет , и дальше проходит*",230400,null],[230416,"2026-09-22T16:03:58",64,"//Ещё минут 10 мне б\n\nВельдьен протягивает билет без прилюдий",230391,null],[230417,"2026-09-22T16:04:01",22,"Вакс шагает вперед, протягивая билет.",226349,null],[230421,"2026-09-22T16:07:13",36,"Вам всем выдают кастрированный билет, где указано ваше место и вы проходите в цирк.\n\nВойдя в него вы ничего не видите ибо было темно, пока последний из вашей четверки не входит внутрь.\n\nРезко включаются светящиеся кристаллы  с характерным  щелчком и шатер заливается светом",226349,null],[230448,"2026-09-22T16:11:59",48,"-..это место довольно..богатое, чтоли? Подозрительно что билет достался мне бесплатно и изнеоткуда..что до вас?",226349,null],[230457,"2026-09-22T16:14:07",22,"Вакс радостно хлопает в ладоши.",230421,null],[230470,"2026-09-22T16:19:00",64,"//а тёмное зрение",230421,null],[230480,"2026-09-22T16:21:04",64,"Глаза Вельдьен загораются, она игриво виляет хвостом осматриваясь по сторонам, одну из рук она держит на бедре, а другая свободно болтается рядом. С небольшим восхищением она говорит, осматривая округу\n—ох.. Эффектно...\nпосле идёт искать свое место",230421,null],[230483,"2026-09-22T16:24:14",48,"Сэдрик, бормоча что-то под нос, наблюдает за реакцией своих спутников, анализируя мимику и жесты. Когда Вельдьен идет на свое место, он решает последовать её примеру и спускается по трибунам на своц ряд..а потом неумело шастает между сиденьями пока наконец не усаживается в одно из них.",226349,null],[230489,"2026-09-22T16:32:40",64,"//терпим",226349,null],[230503,"2026-09-22T16:43:23",44,"* астольфо, идёт на своем место и присаживается. Когда он присел он осматривает это место . Достаточно баготое . Возможно тут есть подвох . *",230255,null],[230650,"2026-09-22T17:21:35",48,"// пам парам пам пам",226349,null],[230997,"2026-09-22T19:34:14",36,"//магическая темнота",230470,null],[230999,"2026-09-22T19:34:48",36,"//так....\n\n@Illidayn \n@Az095as0 \n@dethchinski \n@lady_godzilla \n\nЯ ИСКРЕННЕ извиняюсь. Я уснула из за недосыпа по ночам.",226349,null],[231001,"2026-09-22T19:34:59",36,"//если вы щас можете то давай продолжим",226349,null],[231004,"2026-09-22T19:35:05",36,"// я еще карту проебала",230999,null],[231006,"2026-09-22T19:35:32",64,"Не вайбы уже\n\nДавай другой день",231001,null],[231011,"2026-09-22T19:37:46",36,"//ладушки, еще раз извиняюсь",231006,null],[231015,"2026-09-22T19:38:54",64,"//Извинения дела не правят. Давай нам по 100к опыта за такое и как будто ничего не было",231011,null],[231019,"2026-09-22T19:41:44",36,"Вы получили магический артефакт\n\nУ тебя в руке появляется монета со странными символами из пальцев рук с двух сторон. Ты не понимаешь что они обозначают и что это монета делает, но она красивая",231015,null],[231023,"2026-09-22T19:44:16",48,"//а мне",226349,null],[231024,"2026-09-22T19:44:27",64,"я ему передаю",231023,null],[231025,"2026-09-22T19:44:50",48,"//щас еще кто нибудь спросит и я ему передам",226349,null],[231032,"2026-09-22T19:53:44",64,"//играем в зппп",231025,null],[231033,"2026-09-22T20:01:46",22,"- Ой а что за монетка?!",226349,null],[231034,"2026-09-22T20:01:50",22,"//ну го",226349,null],[231035,"2026-09-22T20:05:49",44,"// уже поздно, я буду дрочить на урок.",231001,null],[231040,"2026-09-22T20:09:33",36,"//ну киньте на анализ, не знаю",231033,null],[231041,"2026-09-22T20:11:36",64,"//на чурок там надеюсь?",231035,null],[231042,"2026-09-22T20:11:37",22,"/r",231040,null],[231044,"2026-09-22T20:11:40",48,"За незнанием, что это за неоьычная монета, он передаёт её следующей в надежде, что та знает как этим воспользоваться",231033,null],[231045,"2026-09-22T20:12:01",36,"....",231043,null],[231046,"2026-09-22T20:12:07",64,"//а вот в пф2 был бы крит",231043,null],[231048,"2026-09-22T20:14:22",36,"Монета \"Фигвам\"\n\nПри броске этой монеты у вас забирается две золотых из инвентаря, а в ответ вы получаете НИ-ХУ-Я",231043,null],[231049,"2026-09-22T20:14:44",36,"Ты понимаешь что её нада подбросить",231044,null],[231055,"2026-09-22T20:21:07",48,"- Это монетка для подбрасывания, я полагаю..но может я знаю меньше чем вы?",226349,null],[231056,"2026-09-22T20:22:09",44,"// на контрольную по математика .",231041,null],[231057,"2026-09-22T20:24:42",64,"//угадал",231056,null],[231059,"2026-09-22T20:25:34",64,"—Может, ты узнаешь больше, если подкинешь?",231055,null],[231061,"2026-09-22T20:26:27",48,"- Я уже передал Вакс. Думал, может она получше взглянет на неё, опытным глазом.",231059,null],[231063,"2026-09-22T20:27:31",22,"Вакс облизала монету.\n\n- Монета как монета. Хочешь покидать?",226349,null],[231066,"2026-09-22T20:32:30",48,"- ..не знаю зачем её окраплять слюной ради этого, ну..\n\nКапюшончик по \"доброму совету\" двух дам кладет сию монетку на большой палец руки, закрытой кожаной перчаткой и..\n\n- ..допустим.\n\nПодбрасывает её 2 раза.",226349,null],[231068,"2026-09-22T20:34:24",22,"- Мы, ааракокры, так познаем мир!",231066,null],[231070,"2026-09-22T20:37:09",48,"- Хм..может хотя бы пару медяков в кошелек привалило.\n\nОн заглядывает в свой кошелек, из под капюшона веет надежду на хоть какую-то выгоду. Ответ убил\n\n- ..а..любопытно",226349,null],[231071,"2026-09-22T20:40:05",48,"- Действительно прикольно. Я пожалуй сохраню эту штуку.\n\nЗагребал эту приколюху в свой карман.",226349,null],[231944,"2026-09-23T14:48:22",48,"//когда вам удобно продолжить?",226349,null],[231957,"2026-09-23T14:49:34",64,"Не щас",231944,null],[231991,"2026-09-23T14:55:52",36,"//не зас",231944,null],[231995,"2026-09-23T14:56:40",48,"//а дальше будет не сас",226349,null],[232292,"2026-09-23T15:56:37",22,"У нас квест отменяется на время, верно?/",226349,null],[232294,"2026-09-23T15:57:19",22,"Мне нужно перераспределить свои ресурсы, поэтому важно понимать. Я не могу в подвешенном состоянии держать перса и слот/",226349,null],[232405,"2026-09-23T16:31:07",36,"//не, квест сегодня продолжиться. Но если темнейшее будет долго идти.... То оно будет уже завтра",232292,null],[232407,"2026-09-23T16:31:33",36,"//вообще он на сесси 2-3\nЕсли норм соберёмся то и за 1 успеем. Но чет как-то не идёт",226349,null],[234283,"2026-09-24T16:48:43",36,"Я щас с документами вожусь... Дайте пожалуйста минут двадцать",226349,null],[234284,"2026-09-24T16:48:43",36,"Извините что долго",226349,null],[234301,"2026-09-24T17:06:46",48,"//прощаем",226349,null],[234313,"2026-09-24T17:11:35",36,"//вааааа",226349,null],[234314,"2026-09-24T17:11:36",36,"Я тут",226349,null],[234315,"2026-09-24T17:12:43",36,"Корояе, из за коротких сроков урежу актов в цирке ибо часа на игру объективно мало",226349,null],[234316,"2026-09-24T17:12:43",36,"// @lady_godzilla \n@dethchinski \n@Az095as0 \n@Illidayn  \nЕсли прям щас соберётесь то тут же и закончим, я проведу грубо говоря что планировала и ваши персы будут свободны",226349,null],[234331,"2026-09-24T17:28:05",22,"//я тут частично, но буду стараться реагировать вовремя👍",234316,null],[234357,"2026-09-24T17:38:49",64,"В живом состоянии? //",234316,null],[234363,"2026-09-24T17:40:52",48,"// Раз контент урезан то думаю шансов сдохнуть у нас меньше.",234357,null],[234371,"2026-09-24T17:46:13",3,"/наоборот",226349,null],[234376,"2026-09-24T17:47:12",22,"Да погнали/",226349,null],[234378,"2026-09-24T17:47:34",48,"//😶",234371,null],[234379,"2026-09-24T17:47:39",36,"//с радостью, только коли нету",234376,null],[234381,"2026-09-24T17:47:46",36,"//позовите его",226349,null],[234382,"2026-09-24T17:47:57",64,"//сама зови",234381,null],[234383,"2026-09-24T17:48:04",64,"//за 50 опыта позову",234381,null],[234384,"2026-09-24T17:48:28",48,"//ему звонить или просто тегнуть",226349,null],[234387,"2026-09-24T17:49:02",64,"@Az095as0 тегнуть каждый дурак может //",234384,null],[234388,"2026-09-24T17:49:17",48,"//а позвонить только совсем отбитый",234387,null],[234389,"2026-09-24T17:49:23",36,"//ну я",234388,null],[234392,"2026-09-24T17:49:50",48,"//я пытался",226349,null],[234393,"2026-09-24T17:49:57",36,"//я тоже",234392,null],[234395,"2026-09-24T17:50:03",64,"//3 долбаеба",226349,null],[234396,"2026-09-24T17:50:12",64,"//я тоже",234395,null],[234398,"2026-09-24T17:50:59",64,"//ого",234397,null],[234400,"2026-09-24T17:51:12",48,"//что там, у меня не грузит",226349,null],[234405,"2026-09-24T17:53:18",48,"//ля а смысл ему звонить если номер купленый..",226349,null],[234409,"2026-09-24T17:54:00",36,"//ну уведы то приходят...",234405,null],[234410,"2026-09-24T17:54:10",36,"//кто у него вообще?",226349,null],[234411,"2026-09-24T17:54:22",64,"//под столом?",234410,null],[234412,"2026-09-24T17:54:28",48,"//дома?",234410,null],[234413,"2026-09-24T17:54:48",36,"//перс",226349,null],[234414,"2026-09-24T17:54:53",48,"//фембой",226349,null],[234417,"2026-09-24T17:55:09",48,"//ходячий сексо-рофл",226349,null],[234422,"2026-09-24T18:08:03",44,"// понятно",234387,null],[234423,"2026-09-24T18:08:13",36,"Вы садитесь по своим местам. Какое-то время ничего не происходит затем вы слышите звон колокола.\n\nОдин удар...\n\nЗатем второй удар... \nПосле второго удара все двери что были открыты когда вы вошли закрылись, а свет погас\n\nТретий удар....\nИ на сцену включается луч света, который освещает пустой центр сцены. После чего вы слышите звонкий веселый женский голос из за кулис\n\n- Дамы и господа!\n\nКороткая пауза\n\n- Какое счастье видеть вас здесь!\n\nЕё голос эхом разносится по шатру\n\n- Ну наконец-то! Я уже начала волноваться!\n\nСлышите вы этот же голос, но уже не эхом, не усиленный. А позади вас, она стоит между рядами кресел, позади вас\n\nПосле чего проходит мимо ваших кресел и подходит к близлежащему, к аракокре\n\n- Вы ведь впервые у нас?\n\nОна протягивает к её лицу трость словно это микрофон, но вы понятия не имеете что это такое",226349,null],[234424,"2026-09-24T18:08:45",36,"// @dethchinski \n@Illidayn \n@Az095as0 \n@lady_godzilla",234423,null],[234425,"2026-09-24T18:08:52",48,"//йоу, да ты прям как хищник выжидала",226349,null],[234426,"2026-09-24T18:10:54",44,"// что такое микрофон в средневековом времени ?",234423,null],[234427,"2026-09-24T18:11:07",36,"//если что, я забыла упомянуть, но когда она заговорила за вами, то свет во всем цирке вновь включился",234423,null],[234428,"2026-09-24T18:11:21",36,"//вот вы и не знаете",234426,null],[234429,"2026-09-24T18:13:00",48,"Когда из неоткуда явился голос дамы, Сэдрик немного дернулся, а потом начал чуть ли не нервно оглядываться по сторонам, благодаря чему первым обернулся на даму. Сейчас он молча пялится сначала на неё, потом на непонятно на какую пилюлю похожий предмет в её руках, потом на Вакс, и так по кругу. Из под капюшона веет заинтересованность..",234423,null],[234430,"2026-09-24T18:13:12",64,"М//",234424,null],[234431,"2026-09-24T18:13:45",36,"//в рука у неё ТРОСТЬ",234429,null],[234432,"2026-09-24T18:13:50",36,"//посох, палка",226349,null],[234433,"2026-09-24T18:14:06",36,"//который она приставила к клюву птице ТИПО микрофона",226349,null],[234434,"2026-09-24T18:14:21",22,"- Да! Тут славно!\n\n*хлоп-хлоп-хлоп*",234423,null],[234435,"2026-09-24T18:14:25",48,"//я сижу и не вижу ничего ниже её кулака",226349,null],[234436,"2026-09-24T18:14:39",48,"//ладно признаю тупанул",226349,null],[234437,"2026-09-24T18:14:47",44,"// так мы не знаем что такой микрофон, в друг это дилдо конструктора",234433,null],[234438,"2026-09-24T18:15:02",48,"//это трость",234437,null],[234439,"2026-09-24T18:15:04",36,"//так я и говорю что это трость",234437,null],[234440,"2026-09-24T18:16:28",64,"фу женщина. Ну Вельдьен удивилась появлению и осмотрела... Кого? Ну вот эту штуку крч, Обернувшись на неё, её глаза 1 раз блестнули в темноте, но она просто молча наблюдает. Сегодня на отдыхе",234423,null],[234442,"2026-09-24T18:20:47",22,"/ребят, давайте я ливну. Я не могу так играть, это не игра, а флудильня. Развлекайтесь сами @Professor_3M653 к тебе вопросов нет, ты чудо🖤",226349,null],[234443,"2026-09-24T18:21:27",22,"Вакс встала со своего места и покинула театр, растворившись в темноте.",226349,null],[234444,"2026-09-24T18:23:22",36,"Она искренне улыбается и радостно восклицает\n\n- Я рада что вам тут нравится! Ведь мне тут тоже нравится!\n\nОна закружилась вокруг себя, тем самым спустившись на пару рядов вниз. Затем она резко остановилась и посмотрела на вас\n\n- Как приятно что вы пришли, я так боялась что придётся начинать без вас...\n\nОна мягко улыбнулась, но слишком загадочно, она опустила голову и тут свет погас, через секунду он вновь включился, но шута рядом не было. Она уже стояла на сцене\n\n- А теперь начнем наше представление! Начнем с простого, с маленького театра, вы же любите театр?...\n\nСцену закрывает занавес пока она в полупоклоне смотрит на вас, затем через пару секунд занавес вновь открывается, но на сцене уже стоит мини городок из картона и бумаги, а по нему ходят несколько маникенов что повествуют историю о том как они пошли в чудеснейший цирк со своими друзьями.\n\nНо друзей пока не было, был парень похожий на астольфо и тифлинг похожий на Велдьен",234434,null],[234445,"2026-09-24T18:23:27",36,"//.....",234442,null],[234446,"2026-09-24T18:23:41",36,"// @Illidayn \n@dethchinski \n@Az095as0 \nА ведь я вас просила....",226349,null],[234447,"2026-09-24T18:26:18",36,"//шут выглядит вот так",234440,null],[234448,"2026-09-24T18:28:01",64,"//я со старта игры не флудил",234446,null],[234450,"2026-09-24T18:28:55",64,"//спасибо",234444,null],[234451,"2026-09-24T18:29:37",36,"//я НЕ помню имени!!!!😭",234450,null],[234456,"2026-09-24T18:32:22",36,"// @Az095as0 \n@dethchinski \n@Illidayn \n\nМне долго ждать реакции?",234444,null],[234459,"2026-09-24T18:35:28",64,"Вельдьен с умеренным восхищением смотрит на это все, её глаза, зрачки которых немного увеличились, постоянно бегают туда-сюда осматривая представление, она контролирует свои эмоции, но по ней, и её влияющему, приподнятому хвосту, видно что ей тут довольно интересно. Она про себя говорит \n—До чего чудесно...",234444,null],[234460,"2026-09-24T18:35:32",48,"- Как всё быстро тут происходит..я прямо-таки восхищен.\n\nВ тени накидки не видно, но глаза капюшончика было не оторвать от дамы, а затем и от сцены. Заметив что среди \"пародий\" не было самого Назгула Сэдрика, он заинтересовался еще более..",234444,null],[234466,"2026-09-24T18:43:35",44,"// мммм дайте полчасика , просто нужно разрешит свое оружие \n* Астольфо, замечает это девочку .  Он в своих мыслях, а она не чё такая , но она не лучше того человека , но я бы тоже бы дал ее . *",234447,null],[234467,"2026-09-24T18:44:03",36,"Затем к тифлингу и предположительно астольыо присоединилась странная фигура в черном капюшоне, похожий на Сэдрика \n\nВы заметили что декорации на фоне стали показывать старую площадь на которой вы стояли\n\nА манекены то и делали что повторяли фразы сделанные вами или повторяли жесты сделанные вами тогда.\n\nУдарил колокол и все три манекена посмотрели на вас со словами\n\n\"Представление начинается\"\n\nЗатем гаснет свет и позади вас под резким включенным светом вновь появляется Сильва, в руках у неё шляпа\n\n- Сейчас я покажу вам фокус!\n\nОна игнорирует ваши негодования и комментарии по поводу театра и просто пару раз неуклюже стукает тростью по волшебной шляпе, а после вытаскивает оттуда кролика (@SwembA) и отдает Вельден.\n\n- Держи, дарю\n\nЗатем улыбается и произносит \n\n- ПУФ!\n\nВновь гаснет свет и она оказывается на сцене где сидит на самом краю свесив ножки и начиная мотать головой из стороны в сторону начинает мотать ногами\n\n- У вас есть вопросы касаемо представления?\n\nСпрашивает она радостным голосом сидя на уже пустой сцене",226349,null],[234470,"2026-09-24T18:45:38",62,"—Отпусти меня, человек!\nКролик обеими ногами бьёт в грудь того, кто его схватил, отпрыгивая назад. Сам кролик выглядит относительно большим и, почему то, умеет разговаривать. Лапы не нанесли большого ущерба, а вот кролик каким то чудом смог вырваться с хватки.",234467,null],[234472,"2026-09-24T18:46:25",64,"//э",234470,null],[234473,"2026-09-24T18:47:08",36,"// ДОПУСТИМ",234470,null],[234475,"2026-09-24T18:47:31",62,"—Как смеешь ты, столь большое существо, пытаться меня хватать? Не наслышан ли ты о величайшем боевом мастере чащи, Харсе? Если нет, то тебе предстоит вкусить удары моих лап!\nХарс выглядит полностью готовым к битве , бешено размахивая руками и избивая, видимо, воздух.",234470,null],[234476,"2026-09-24T18:47:42",62,"Харс.",226349,null],[234477,"2026-09-24T18:47:48",64,"Вельдьен ошарашено не успевает схватить кролика как тот убегает, она явно не ожидала подобного и сидит в не самом уверенном для себя выражении лица, в телом ее тело как то замерло, в грудь её не пришлось бить",234470,null],[234478,"2026-09-24T18:48:02",64,"//да ты че дай успею среачить",234475,null],[234479,"2026-09-24T18:48:11",64,"Женщину он пиздит //",226349,null],[234482,"2026-09-24T18:49:58",48,"-..какое любопытное создание..разумное и к тому же бунтарное..\n\nТёмная фигура наёмника встала около Харса и стала сверлить его морду непроглядным взглядом\n\n- Какого это..сидеть в шляпе..Харс?",234475,null],[234484,"2026-09-24T18:51:01",64,"—М.. Кролик.. Харс? медленная пауза —если ты вправду кролик - у нас есть общее\nНу она не боится, Вельдьен начинает потихоньку отходить от увиденного и смотрит на него уже уверенно, активно виляя хвостом \n—ммм, не дерзи. Не моя вина что тебя мне дали",234475,null],[234485,"2026-09-24T18:51:11",62,"—Ты чё, темный хмырь, давно по своей тьмовой морде не получал да!? Ну так иди сюда, ты!\nХарс продолжает бить воздух кулаками, произнося боевой клич(со стороны это бешеный писк). Он делает это пока не выдохнется, что происходит довольно быстро.",234482,null],[234486,"2026-09-24T18:52:13",62,"—Не будешь...фух...ух...ты мне сородичем! Тебя...ух...не кусали феи!\nДвижения все более вялые, а он продолжает, видимо, боксировать с воздухом, тяжело дыша и набирая воздуха в легкие",234484,null],[234487,"2026-09-24T18:53:54",48,"-..стоило ожидать.\n\nСэдрик все так же, толи надменно, толи ошарашено но так же неподвижно глядит на кроля. Он стал выжидать, пока тот выдохнется, а после поднял правую руку с открытой ладонью в знак мирных намерений\n\n- Предлагаю вам присесть..господин Харс..выглядите усталым.",234485,null],[234490,"2026-09-24T18:55:09",64,"—Феи? Мм, ну меня пытались. Короткая пауза —А в сородичи я не лезу\nВельдьен внимательно смотрит за кроликом, изредка виляя хвостом, взгляд не хищный, как на жертв суккубовских, а скорее заинтересованный",234486,null],[234492,"2026-09-24T18:55:30",62,"—Конечно я устал, ты, тьмовая..ух..морда! Вы заставляете меня показать мою полную ярость! Я не сдамся и не поддастся на ваши...фух..убеждения и обманы!\nСпустя еще секунд 30 боксирования перед лицом фигуры, Харс полностью выдыхается, наконец садясь на пол.",234487,null],[234493,"2026-09-24T18:56:39",62,"—Фух...ух..пытались не..значит что кусали! Ух...\nОн указывает на себя лапой, а после на Вельден, вертя у, похоже, виска? \n—Из-за..фух..их шуток я стал подобным вам...ух..эгоистичным и греховным существом!",234490,null],[234495,"2026-09-24T18:58:02",48,"Капюшончик взглядом преследует движения кроля, наклонив голову направо от сметения..\n\n-..я имел в виду..присесть на кресло, но как вам угодно. \n\nПосле он, наконец отвлекшись ненадолго от кролика, мирно присел на свое место.",234492,null],[234496,"2026-09-24T18:59:33",64,"на секунду на лице Вельдьен появляется ухмылка, но после возвращается наигранный тон\n—Ты так быстро устал? Нуу... Короткая пауза —не удивительно, что тебя поймали\nОткидывается назад, поправляя нижнюю часть одежды",234493,null],[234497,"2026-09-24T18:59:34",62,"—Итак! Ух... Кто вы вообще!? И как я тут оказался? Что это за место? Я спокойно ел траву, как вдруг меня вытащили тут!?\nХарс садиться на задние лапы, осматривая все вокруг. Он выглядит искренне заинтересованным в способе попадания сюда, но хвоста он не поджал. Интересуется не из-за страха, а из-за чистого любопытства.",226349,null],[234498,"2026-09-24T19:00:23",64,"//ща я хавать насыплю, минут 5",226349,null],[234500,"2026-09-24T19:00:57",62,"—Поймали!? Никто не мог поймать меня, великого Харса! Я лучший боец своей чащи, а вы лишь жалкие существа что подобны людям! На смей судить меня по своим стандартам, женщина!\nХарс дерзко показывает тебе кулак лапой, намекая о будущем если такое отношение к его небольшой туше продолжиться",234496,null],[234501,"2026-09-24T19:00:59",64,"—Вельдьен\nкоротко кивая отвечает тифлинг",234497,null],[234502,"2026-09-24T19:01:01",44,"// отлично , просто я потерял нить повествование . К стати, Пон обедит",234498,null],[234503,"2026-09-24T19:01:34",48,"Сэдрик обратил капюшон на Сильву. \n\n- А вот это уже вопрос к организатору этого мероприятия. А я - Сэдрик, наёмник.",226349,null],[234505,"2026-09-24T19:03:31",62,"—Фух...я уже представлялся! Харс, великий боец из \"Чащи\", который был покусан феями! По вашему меня звали Харенгоном, но это ложь!\nХарс ищет то самое кресло о котором говорил Сэдрик, что бы самостоятельно сесть на него задними лапами. Напуганным он не выглядит, скорее находиться в замешательстве из-за внезапного своего появления.",234503,null],[234506,"2026-09-24T19:05:25",36,"//вы смотрели представление. Оно стало подозрительным, затем оно резко закончилось с акцентом на вас. Потом за вашими спинами появилась шут и достала из шляпы кролика, который стал буянить, а шут в свою очередь вернулась назад на сцену",234502,null],[234511,"2026-09-24T19:09:09",64,"—Вы грубиян, Харс—короткая пауза—Хам и животное!\nХвост Вельдьен обвился у лыдашки и та отвела взгляд в сторону, скрестив руки на груди, и выдохнув. Глубоко вдохнув и выдохнув подъебывая кролика дыхалкой",234500,null],[234513,"2026-09-24T19:10:04",62,"—Ээ!? Хам!? Животное!? ВЫ ДОСТАЛИ МЕНЯ КАК ПОТЕХУ ДЛЯ ЗРИТЕЛЕЙ, А Я ХАМ!? Наглое людоподобное существо! Как ты смеешь подгребать меня под свои стандарты поведения, а!?",234511,null],[234514,"2026-09-24T19:10:22",44,"// я понял , просто когда отходил  чтобы разрешить потронов , то вы тут написали про кролика который избежал женщунику сукуб и его фей ебали . \n* Астольфо , внимательно смотрит на этот цирк . Кролик который появился из шляпы , а после начал избежать сукубшу . Астольфо, понял , что  Харс , раньше встречался с феями ,  Как и он  .  Но астольфо феи его выебали , а вот с Хаосом просто покусали . Но все равно у астольфо понравилось этот небольшой цирк *",234506,null],[234515,"2026-09-24T19:10:28",62,"Харс снова активизируется, уже готовясь для прыжка через пол зала, что бы на прыгнуть на Вельден",226349,null],[234518,"2026-09-24T19:12:09",48,"- Ну вот, вы уже разочаровали прекрасную даму, господин Харс...а теперь я прошу вас..\n\nОн резко обернулся на Кроля и направил в его сторону указательный палец, после чего прошептал..тихо, но так чтобы все в укруге слышали эхо этого шепота\n\n- СЯДЬ\n\n//приказ, спас мудрости",234515,null],[234520,"2026-09-24T19:12:52",64,"—пф.. коротко выдохнула в ответ Вельдьен, не смотря на Харса\n—Да, вы - Хам.",234513,null],[234521,"2026-09-24T19:13:02",62,"/r +3",234518,null],[234523,"2026-09-24T19:14:23",62,"—Как я могу быть хамом, когда ты – та, кто желала веселья за счёт живого существа, А!?\nХарс чувствует давление со стороны голоса, но старается не реагировать, прижав уши к голове. Он перестал набирать обороты для прыжка, отложив драку на потом",234520,null],[234524,"2026-09-24T19:16:06",64,"—Подумай\nна кролика та не смотрит, лишь посмотрела на Сэдрика и кивнула ему, в знак благодарности",234523,null],[234525,"2026-09-24T19:17:16",48,"//всрать ячейку красиво надо уметь.\n\nТканевая накидка Сэдрика затряслась вместе со сказанным в последнюю очередь, и успокоилась спустя мнгновение, после чего капюшончик вернулся в свое изначальное положение, крепко ухватившись левой рукой за край кресла.\n\n-..думаю поладить есть способ..прийти к согласию нужно будет..как нибудь позже. Чувствую, представление скоро возобновится.",226349,null],[234527,"2026-09-24T19:18:12",62,"—О чем подумать? О чем подумать, а!? Ты совсем что ли логики не имеешь, женщина! Вы меня сюда затащили, а теперь держите как игрушку? Я так просто не сдамся поняла ты!?",234524,null],[234532,"2026-09-24T19:19:12",36,"Пока вы срались на вас все это время с улыбкой на лице смотрела шут, по имени Люсиль (Да не Сильв, я просто опять имя забыла). Она наблюдала за вашими ссорами иногда тихонько хихикая и продолжая вилять ногами из стороны в сторону",226349,null],[234533,"2026-09-24T19:19:55",64,"мудрые слова обновили состояние Вельдьен, она выдохнула и расслабилась... Или это было наигранно? Но, в любом случае, она просто села ровно, с тем же выражением лица, чуть восхищенным, что было до кролика, смотря на сцену \n—Пожалуй, да.. Короткая пауза—В конце концов мы на шоу, а не ссориться пришли...",234525,null],[234537,"2026-09-24T19:21:20",62,"—Что за шоу вообще?\nХарс садиться обратно, смотря на сцену. Он не понимает что может быть хорошего в такой темной и неуютной обстановке. Как заяц он не желал смотреть на \"представление\", что тут скоро развернется, но выбора не было.",226349,null],[234538,"2026-09-24T19:22:53",64,"—Ладно не сердись, разрешаю быть добрым\nтихо хихикнула в ладошку, с нейтральным лицом \n—Потом за свое эго честь отстаишь. Короткая пауза......  —Ты ведь тут не ради этого",234527,null],[234539,"2026-09-24T19:25:21",62,"—Да, да, точно! Зачем я тут вообще?\nХарс теряет запал, смотрит то на шута, то на эту ведьму, то на тьмучела, пытаясь составить какую то цепочку у себя в голове.",234538,null],[234540,"2026-09-24T19:25:29",48,"- Хороший на самом деле вопрос..\"Что за шоу\". Всё, что тут до этого момента произошло навевает на меня сомнения..\n\nОн стал вдумчиво смотреть на Сцену, не двигаясь но ослабив хватку..как вдруг вспоминает про того мужика, что пропал сразу после появления Шатра.\n\n- ..не с проста всё это..билеты из неоткуда..разумный кроль..пересказ наших диалогов..",226349,null],[234542,"2026-09-24T19:26:20",48,"- И этот..шляпник..",226349,null],[234543,"2026-09-24T19:26:32",64,"@Professor_3M653 дальше по сюжету веди нас //",226349,null],[234545,"2026-09-24T19:27:53",36,"На сцене бодро покачивая ногами сидел шут и улыбался\n\nУвидев на себе ваш взгляд она бодро и весело помахала вам рукой\n\n- Я всё еще жду вашего акта!\n\nВоскликнула она",226349,null],[234548,"2026-09-24T19:30:25",64,"—что..?\nв недоумении спросила про себя Вельдьен замерев и с подозрением осматриваясь вокруге, хвост ее замерел, а глаза раскрылись немного шире",234545,null],[234549,"2026-09-24T19:30:34",62,"—Эй, что за акт, людоподобное существо?\nХарс смотрит на Вельден, а потом на шута, не понимая что за акт просит это странное создание",226349,null],[234551,"2026-09-24T19:32:35",48,"Сэдрик приподнял голову, ожидая больших подробностей от шута и готовясь к худшему..",226349,null],[234552,"2026-09-24T19:32:53",36,"- Ну же....\n\nОна демонстративно расплылась на сцене словно ей было уже не в терпёж ждать\n\n- Вы же уже должны были понять, ну не заставляйте меня говорить, это.... Иначе не будет так интересно",226349,null],[234554,"2026-09-24T19:34:09",48,"//Я могу кинуть на проницательность чтобы понять что эта падла имеет в виду?",234552,null],[234555,"2026-09-24T19:34:19",36,"//кидай",234554,null],[234556,"2026-09-24T19:34:27",48,"/r +4",226349,null],[234559,"2026-09-24T19:34:46",44,"// так мы показали акт насилие над животными",226349,null],[234560,"2026-09-24T19:34:50",36,"Ты все еще не понимаешь что от тебя хочет шут, ты думаешь что она надсмехается над вами",234557,null],[234561,"2026-09-24T19:34:59",64,"/r +2 я тоже хочу кинуть",226349,null],[234563,"2026-09-24T19:35:01",62,"—Точно, боевое шоу! Эй, тьмомордый! Пошли драться!\nХарс запрыгивает на стену, встаёт в классическую боевую стойку и лапой подзывает к себе фигуру из тьмы, что бы показать великий (не)показательный бой",234552,null],[234564,"2026-09-24T19:35:07",36,"Ты все еще не понимаешь что от тебя хочет шут, ты думаешь что она надсмехается над вами",234562,null],[234565,"2026-09-24T19:35:07",64,"//пик",234562,null],[234566,"2026-09-24T19:35:58",36,"В тебя прилетает плюшевый мячик, не сильно больно. Но неприятно\n\n- Непраааавильно)\n\nОна хихикнула и улыбнулась",234563,null],[234568,"2026-09-24T19:36:34",62,"—Бве..\nКролик чувствует слабый удар в морду, а после потирая подбородок смотрит на шута, пытаясь понять что ему надо",226349,null],[234569,"2026-09-24T19:36:41",48,"-..Ты что, совсем идио-\n\nНе успевает Сэдрик, уже раздраженно привставший с кресла, договорить, как в Харса прилетает игрушка. \n\n-..",234563,null],[234570,"2026-09-24T19:37:04",62,"/r +5",226349,null],[234572,"2026-09-24T19:37:13",62,"Проницательный кроль.",226349,null],[234574,"2026-09-24T19:37:45",36,"Ты понимаешь... Что ты не понимаешь, ведь ты не видел полной картины что видели другие. Ты понимаешь что другие точно знают, но не могут понять.",234571,null],[234576,"2026-09-24T19:38:13",36,"Но шут ждет от вас ответа, или действий",234574,null],[234579,"2026-09-24T19:39:02",62,"—Бфуэ...вот же! Ну, странные почтилюди, напрягите свой \"большой\" мозг и предложите что нибудь!\nХарс ругается, показывая кулаком на \"зрителей\", а в его голосе на моменте мозга слышиться сарказм",226349,null],[234580,"2026-09-24T19:39:10",64,"Вельдьен подсаживается ближе к Сэдрику, и напевает спокойную мелодию на флейте, чтобы тот понял лучше. Вдохновение и помощь на решение детской задачки",226349,null],[234584,"2026-09-24T19:39:49",64,"//можно он ещё раз кинет?",234580,null],[234588,"2026-09-24T19:40:12",64,"@Illidayn кинь ещё раз с приемуществом и вдохновением д6//",226349,null],[234590,"2026-09-24T19:40:22",48,"//секунду",226349,null],[234593,"2026-09-24T19:41:26",48,"Послушав тихую но достаточно смвсловую мелодию, он что-то шепнул..Причем Харс осознает, что шепчет он на Бездне: \"Как удобно\"..",234580,null],[234594,"2026-09-24T19:41:42",48,"/r +d20+6",226349,null],[234598,"2026-09-24T19:42:03",64,"@Professor_3M653 мы победили? //",234595,null],[234600,"2026-09-24T19:42:18",64,"//не потратил",234594,null],[234601,"2026-09-24T19:42:25",64,"//24",234595,null],[234602,"2026-09-24T19:42:36",48,"//ой, я забыл д написать",226349,null],[234603,"2026-09-24T19:42:42",48,"//+4*",234594,null],[234604,"2026-09-24T19:42:45",64,"//все ок все ок",234602,null],[234605,"2026-09-24T19:42:48",64,"//оставь",226349,null],[234609,"2026-09-24T19:44:42",36,"Ты понял что ты слишком силен в загадках, а потому загадка этого глупого шута тебя не заставила усомниться в своей гениальности. Ты понял что она имеет ввиду, ВЫ актёры в этом театре, ВЫ должны показывать представления из брошюры, а она... Она ваш босс, что говорит вам что делать, даёт сценарии... Но не прямо, намекая.... Словно надсмехается, словно шут",234595,null],[234611,"2026-09-24T19:45:19",44,"// ну тогда , щас станцию стриптизм",234609,null],[234618,"2026-09-24T19:47:32",64,"//о у меня есть умение на флекс стрептиза и очарование до 3 человек которые на это смотрели",234611,null],[234621,"2026-09-24T19:47:59",62,"🥲🥲",226349,null],[234623,"2026-09-24T19:48:23",48,"- ..Так актёры это мы.\n\n//щас я перечитаю че было на сцене до этого. Щас отец раскусит сучку, щас..",226349,null],[234632,"2026-09-24T19:51:57",64,"а шут женщина?",234576,null],[234633,"2026-09-24T19:52:08",44,"// ты что тоже бард коллеги очарование ?",234618,null],[234641,"2026-09-24T19:54:48",64,"—Поняла.. Но только это.\nВельдьен встаёт, каст чудотворства на увеличение громкости и шуту говорит, не громко, тихим, обычным голосом \n—простите, но мы не поняли что именно нам нужно делать",234623,null],[234644,"2026-09-24T19:56:32",36,"Шут резко остановилась \n\nПодняла голову и тяжело выдохнула, затем словно пьяница достала из-за пазухи бутылочку и стала пить оттуда. Причём так долго, что она должна была бы уже опустеть, но видимо еще нет",226349,null],[234649,"2026-09-24T19:57:30",44,"// щас поймёшь. \n* Астольфо , услышал от дед инсайда , что мы  актеры , то астольфо встаёт из своего места и идёт на цену * \n--- как и знал , что бесплатный  сыр только в мышеловке. \n* Потом это суккуб начал кричать . Но ему не важно это *\n--- эй шут . Тебе нужен шоу . Так что давай я тебе и устрою . \n* Астольфо начинает танцевать и выступить . Астольфо танцует разные эротические танцы. Чтобы привлечь внимание *",226349,null],[234658,"2026-09-24T20:00:34",62,"—Какой это ужас.\nХарс откровенно говоря с отвращением смотрит на это выступление, но принимает эту крайность",226349,null],[234661,"2026-09-24T20:01:49",36,"Астольфо получает мячиком в табло после пары его пируэтов\n\n- Зал с танцами не здесь",234649,null],[234663,"2026-09-24T20:02:00",48,"Сэдрик кладет правое колено на край кресла и опирается головой о кулак, наблюдая за сим, и снова что-то шепчет на Бездне. Харс слышит: \" Куда меня занесло это странствие..\".\n\nПосле он, через силу, пытается подыграть проституту, потому как выбора особого нет.\n\n- Ого, вот это прыть! Он чёртов акробат! Как ему так удается??\n\nИ локтем пихает Вельдьен, чтобы та тоже что-то выкрикнула.",234649,null],[234664,"2026-09-24T20:02:01",44,"// минута прошла хотя бы ?",234661,null],[234665,"2026-09-24T20:02:24",48,"-..не помогло.",234661,null],[234668,"2026-09-24T20:03:10",36,"//12 секунд",234664,null],[234673,"2026-09-24T20:03:56",44,"// :( . Ну тогда . Иди нахуй , я обиделся .",234668,null],[234675,"2026-09-24T20:04:10",44,"// не дали станцевать стриптизм",234673,null],[234676,"2026-09-24T20:04:19",64,"—Поняла..\nВельдьен берет мячик, который кинули в кроля и волшебной рукой который кинули в Фембоя. После чего подходит к сцене, жонглируя мячами",234661,null],[234677,"2026-09-24T20:04:30",64,"/roll@roll_bot 1d20+7 выступление",226349,null],[234679,"2026-09-24T20:04:34",64,"Везунчик",226349,null],[234682,"2026-09-24T20:04:39",64,"Умом",234680,null],[234685,"2026-09-24T20:05:17",44,"// к стоит, я наверное тоже должен было кинуть на выступление но протупил .щас тоже кину",226349,null],[234686,"2026-09-24T20:05:45",44,"/r 1d20+8+1d4",234685,null],[234690,"2026-09-24T20:05:55",64,"Пиздец",234687,null],[234695,"2026-09-24T20:06:29",36,"- Это конечно прикольно, но не то\n\nТы тоже получаешь мячиком в табло\n\n- Вы вообще афишу читали?...\n\nГоворит она уставшим и раздосадованным голосом, словно она явно расстроилась в вас",234680,null],[234699,"2026-09-24T20:07:37",48,"- ..какую афи..хотя постойте ка.\n\nСэдрик опускает взгляд на поясную сумку и достаёт билет, осмотрев затем со всех сторон.",234695,null],[234706,"2026-09-24T20:08:42",44,"// как я понимаю уже поздно. Но ладно",234687,null],[234709,"2026-09-24T20:09:16",64,"—Театральная сцена...\nПам пам пам, смотрит на Астольфо, как на того кто показал уже выступление и, кажется, может помочь разыграть сценку, а потом на шута в лёгком недоумении",234695,null],[234711,"2026-09-24T20:09:37",36,"Шут запоминает твой красивый танец, но ты все равно получил тогда мячиком в лицо. Может потом за это что-то получишь?",234706,null],[234712,"2026-09-24T20:10:29",36,"- Афишу а не билет....\n\nВ тебя тоже прилетает мячик, который слабо ударяется в твой лоб, ведь она уже не видит смысла метать их в вас и просто ложиться на пол",234699,null],[234715,"2026-09-24T20:11:12",62,"—Какой же это...идиотизм.\nХарс окончательно выходит из себя, осматриваясь вокруг на поиски чего то, что цепляет взгляд.",226349,null],[234716,"2026-09-24T20:11:18",62,"/r +5 внимательность",226349,null],[234718,"2026-09-24T20:11:21",44,"* астольфо, был разочарован , тем что его шлючи танцы не было должным образом оценены . Так что он возвращается обратно на свое место *",234711,null],[234723,"2026-09-24T20:12:31",48,"Из-за прилетевшего мяча взгляд снова устремлен на Шута.\n\n-..да какая АФИША?! \n\nОн резко встает со своего места, указав пальцем на Люсиль\n\n- Мы сюда как зрители пришли!",234695,null],[234725,"2026-09-24T20:13:24",36,"Ты замечаешь 4 большие двери напротив сцены по две с каждой стороны. Это аномально большие массивные двери с соответствующими рисунками над ними\n\n\"нота\", \"Меч\", \"Клетка\" и \"лента\"",234717,null],[234727,"2026-09-24T20:14:19",36,"- Сразу видно, не умеете читать невидимый микрошрифт вписанный магией в структуру ваших картонных билетов\n\nГоворит она это так, будто это было очевидно",234723,null],[234729,"2026-09-24T20:14:37",64,"—Или Шоу было..\nну пытается на флейте играть тогда, виртуозно обыгрывая ноты, исходящие из неё",234709,null],[234730,"2026-09-24T20:14:59",62,"—Нота, меч, клетка, лента...\nХарс пропрыгрвает по залу до Клетки, пытаясь открыть дверь своими небольшими лапами.\n—Ну же...давай!",234725,null],[234733,"2026-09-24T20:15:52",64,"/roll@roll_bot 1d20+7 ну давай кубик, ракай",234729,null],[234738,"2026-09-24T20:16:56",36,"В ответ ты слышишь громкий тяжелый рык за дверью, от чего ты машинально отскакиваешь назад",234730,null],[234739,"2026-09-24T20:16:59",48,"//проклятье, ну почему воззвания со второго..",234727,null],[234741,"2026-09-24T20:17:51",48,"- Представьте себе. \n\nСэдрик показательно разводит руками, выражая возмущение.",234727,null],[234742,"2026-09-24T20:17:55",64,"@Professor_3M653 не то? //",234729,null],[234743,"2026-09-24T20:18:11",62,"—Ох ты...медведи? Да я таких жирдяев в своей чаще!...стоит повременить...\nХарс быстро прыгает до следующей двери – меч. Его лапы редко касаются пола из-за передвижения прыжками",234738,null],[234754,"2026-09-24T20:20:28",36,"Ты очень красиво и виртуозно поешь, от чего настроение шута поднимается, она делает последний глоток из бутыли и убирает её за пазуху. Затем встает взяв в руки посох и ПУФ легкая дымка. Когда дымка пропадает она оказывается около дверей где стоял кроль\n\n- Ладно, раз моя задача вести вас, то я вам расскажу правила нашего мааааленького представления. В этом зале спрятан ключ, от одной из этих четырёх дверей.\n\nОна указывает на каждую дверь своей тростью\n\n- Ваша задача, побывать в каждой двери, поучаствовать в каждом акте, а после получить награду за выступление! Как утешительный приз дам вам это, уж больно мне понравилась игра на флейте\n\nОна стукнула тростью по полу два раза и каждому в руки упала корзинка попкорна, как в кинотеатрах",234734,null],[234757,"2026-09-24T20:21:59",44,"// значит критт на шлючий танец хуйня полян . А тут тудку подул и сразу же так . Понятно кого дм больше любит .",234754,null],[234759,"2026-09-24T20:22:38",48,"- Чщщ..ключ значит. \n\nЕще не отрезвев от неприязни к сей персоне он стал оглядывать сиденья на своём ряду",226349,null],[234761,"2026-09-24T20:22:46",48,"/r +4 восприятие",226349,null],[234762,"2026-09-24T20:22:46",64,"//так дм демон котик, понятно что черту поблажки будут",234757,null],[234767,"2026-09-24T20:23:21",64,"//ну мне пора хули",226349,null],[234769,"2026-09-24T20:23:34",64,"//на минут 15",226349,null],[234770,"2026-09-24T20:23:37",36,"//я просто тебе потом награду дам, она не фанатка стриптиза",234757,null],[234772,"2026-09-24T20:23:46",36,"//но усердия твои она заметила",234770,null],[234773,"2026-09-24T20:24:11",64,"//наныл",234770,null],[234774,"2026-09-24T20:24:14",44,"// а да , мне как раз КД на перезарядку  закончилось .",234770,null],[234775,"2026-09-24T20:24:19",36,"Ты замечаешь след из маленьких крошек, попкорна. Хотя вы только только мх получили",234763,null],[234780,"2026-09-24T20:25:54",48,"Положив на своё сиденье корзину, тёмная фигура, наклонившись, стремительно последовал за этим следом.\n\n- Либо тут плохо убирают трибуны..либо..",226349,null],[234789,"2026-09-24T20:29:37",64,"Ну Вельдьен идёт к дверям. О круто карзинка попкорна. В инвентарь",234754,null],[234807,"2026-09-24T20:38:00",62,"Харс пытается открыть дверь со знаком меча.",226349,null],[235483,"2026-09-25T15:02:41",36,"Ты идешь по следу и доходишь до 7 ряда 69 места",234780,null],[235484,"2026-09-25T15:02:58",36,"Ты подходишь к дверям и видишь кролика что скребётся в дверь с мечом",234789,null],[235485,"2026-09-25T15:03:03",36,"Атлетику прокинь",234807,null],[235493,"2026-09-25T15:12:35",62,"/r -1",226349,null],[235495,"2026-09-25T15:16:14",62,"Харс делает сильную распрыжку – от стен, двери, пола, а после влетает в дверь с обеих своих лап, снося ее к чертям и феям, что его когда то покусали.",226349,null],[235500,"2026-09-25T15:18:04",64,"остальные двери какие напомни",235484,null],[235511,"2026-09-25T15:25:58",62,"Лента, Клетка и Нота.",226349,null],[235516,"2026-09-25T15:27:21",48,"Сэдрик встаёт во весь рост, чтобы понять куда его занесло. Просканировав трибуны он оглядывает место до которого добрался на предмет ключа, если это конечно след к ключу.",235483,null],[235678,"2026-09-25T16:35:23",36,"//я не буду это комментировать....",235494,null],[235680,"2026-09-25T16:36:47",36,"Ты влетаешь в дверь с двух лаб пробивая её лапами, а потом словно в замедленном режиме ты чувствуешь как влетаешь своим тазом в остатки дверь Кроша свои бубенчики на пару с ней и залетая в тёмное помещение помещение",235495,null],[235683,"2026-09-25T16:40:28",62,"Харс быстро осматривается, принимая боевую стойку пьяных мастеров его чащи.\n—Хия! Кто на меня!? НУ КТО НА МЕНЯ??",226349,null],[235684,"2026-09-25T16:41:32",36,"//на этом пока все. У меня эта комната не была готова\nА генерации иссякли",235683,null],[235845,"2026-09-25T17:59:30",48,"/r +4 восприятие",235516,null],[240029,"2026-09-28T10:00:19",36,"Ты изучаешь трибуны и находишь под одним из кресел бумажку с лицом Шутихи, что сидела на сцене. \n\nОна улыбалась на записке, а на записке было написано\n\n\"Ключ там, где вы\"\n\nПосле записка засветилась и ты почувствовал что что-то изменилось в тебе",235845,null],[240030,"2026-09-28T10:01:12",36,"// @lady_godzilla, @Az095as0, @dethchinski, @SwembA\n\nИгра будет через: 10-30 минут, зависит от того как быстро вы пройдёте",226349,null],[240031,"2026-09-28T10:02:22",64,"//через 2-1.5 часа",240030,null],[240032,"2026-09-28T10:02:47",62,"У меня пары.",226349,null],[240033,"2026-09-28T10:02:56",44,"// иди нахуй , у меня пары.\nС любовью",240030,null],[240034,"2026-09-28T10:03:28",36,"//у меня думаете нет пар?)",240033,null],[240035,"2026-09-28T10:03:35",36,"//Я поэтому и тегаю вас",226349,null],[240039,"2026-09-28T10:08:35",36,"//дохуя... Ну ок",240031,null],[240040,"2026-09-28T10:13:07",48,"//я один проспал пары?",226349,null],[240041,"2026-09-28T10:13:22",62,"Прекращайте флудить понемногу.",226349,null],[240069,"2026-09-28T11:27:30",64,"//ну я тут если что",240031,null],[241285,"2026-09-28T20:37:38",36,"// @lady_godzilla, @Az095as0, @dethchinski, @SwembA\n\nКороч, сегодня у меня настроение не водибельное было. А потому предлагаю вот что. Давайте вы напишите когда завтра сможете, а я в это же время постираюсь присутствовать, только не вечером. Вечер у меня забит",226349,null],[241310,"2026-09-28T20:42:58",62,"Завтра до 3-4 занят.",226349,null],[241323,"2026-09-28T20:44:24",64,"//Пффф женщины, ну ок. Мне не совсем удобно будет но я буду",241285,null],[241379,"2026-09-28T20:53:04",36,"//а я после этого времени...",241310,null],[241429,"2026-09-28T20:59:40",44,"// после 23:59 . вот когда я смогу .",241285,null],[241592,"2026-09-28T21:33:48",36,"//хорошая шутка, мне не нравится",241429,null],[241601,"2026-09-28T21:34:55",44,"// это называется когда хочешь получить повышенную степеньдию",241592,null],[242491,"2026-09-29T15:41:04",64,"Доебывай че уж //",241285,null],[242492,"2026-09-29T15:41:43",36,"//ну.....",242491,null],[242493,"2026-09-29T15:42:27",36,"//нэт)",226349,null],[242502,"2026-09-29T15:45:21",64,"//на какую кнопку автовин сделать",242493,null],[242518,"2026-09-29T15:51:55",36,"Ээээ",242502,null],[242520,"2026-09-29T15:52:12",36,"//найди кнопку запуска у рпг",242519,null],[242521,"2026-09-29T15:52:21",36,"//и будет автоовин",226349,null],[242528,"2026-09-29T15:55:18",36,"//Пиздятся палками",226349,null],[242537,"2026-09-29T15:59:08",64,"//у них досуг на днд больше похож чем у нас",242528,null],[242913,"2026-09-30T11:19:02",36,"// @lady_godzilla, @Az095as0, @dethchinski, @SwembA\n\nНу с этим нада чет делать",226349,null],[242914,"2026-09-30T11:19:08",36,"//когда сегодня играем?",226349,null],[242915,"2026-09-30T11:19:28",48,"//почему ты меня не тегаешь😭",226349,null],[242916,"2026-09-30T11:19:40",36,"//Так нада",242915,null],[242917,"2026-09-30T11:19:45",36,"//я всех игроков тегаю",226349,null],[242918,"2026-09-30T11:21:22",64,"//ну я сегодня хотел своих быстренько провести",242914,null],[242935,"2026-09-30T11:33:46",44,"// убей меня пж .",242913,null],[242941,"2026-09-30T11:35:00",36,"//обязательно, но не сейчас. Дойдём",242935,null],[242942,"2026-09-30T11:35:09",36,"//ну ужели два часика",242918,null],[242944,"2026-09-30T11:35:10",36,"Пж",226349,null],[242945,"2026-09-30T11:35:18",36,"//сами себя задерживаете же",226349,null],[242962,"2026-09-30T11:53:09",64,"//к вечеру нормально будет?",242942,null],[242964,"2026-09-30T11:55:53",36,"//ну.... Я планировала с братом поиграть",242962,null],[242965,"2026-09-30T11:56:35",64,"\"//сами себя задерживаете же\"",242964,null],[242966,"2026-09-30T11:56:46",64,"\"//сами себя задерживаете же\"",241285,null],[242971,"2026-09-30T11:59:26",36,"Так давай днем, а ты свою игру на вечер перенесёшь",242966,null],[242980,"2026-09-30T12:01:15",64,"//нормально 1 человека на день перенести или 4",242971,null],[243054,"2026-09-30T12:45:00",62,"Я готов играть.",226349,null],[243842,"2026-09-30T17:08:59",36,"// @lady_godzilla, @Az095as0, @dethchinski, @SwembA\n\nИграть?)",226349,null],[243844,"2026-09-30T17:10:01",62,"Я готов.",226349,null],[243847,"2026-09-30T17:10:52",64,"В целом",243842,null],[243848,"2026-09-30T17:10:56",64,"Можно",226349,null],[243855,"2026-09-30T17:12:14",36,"Ты видишь эту комнату",243844,null],[243856,"2026-09-30T17:12:23",36,"//Напомни, что ты делал?",243848,null],[243857,"2026-09-30T17:12:52",64,"окей я иду следом за кроликом",235484,null],[243859,"2026-09-30T17:13:32",36,"Ты приоткрываешь дверь, что пробил кролик своими ногами и видишь перед собой помещение",243857,null],[243860,"2026-09-30T17:13:40",64,"//на пару-5 минут отойду, щас",226349,null],[243862,"2026-09-30T17:14:19",62,"—Хмм?\nХарс осматривает эту комнату, внимательно вглядываясь в детальки",243855,null],[243905,"2026-09-30T17:23:10",64,"Вельдьен осматривает помещение, полноценно входя туда и проходя вперед, чуть виляя бёдрами и с интересом осматриваясь, чуть наклонив в бок голову \n—Чудное место.. Арена?",243855,null],[243921,"2026-09-30T17:26:06",36,"// @Illidayn \nНапомни свой запрос",226349,null],[243922,"2026-09-30T17:26:15",48,"//.",240029,null],[243923,"2026-09-30T17:26:29",36,"//жду реакт",243922,null],[243924,"2026-09-30T17:26:37",36,"//ща",243905,null],[243940,"2026-09-30T17:28:39",48,"– Как любопытно..\n\nСэдрик некоторое время смотрит на записку, а после замечает громкое пробитие одной из дверей около сцены\n\n–..Позже с тобой поговорим, необычный кусок бумаги.\n\nПосле засовывает фотографию с запиской в капюшон и перепрыгивая через ряды трибун быстро нагоняет своих товарищей.",240029,null],[243953,"2026-09-30T17:30:52",36,"Ты замечаешь шута что сидит на болконе , прямо на пиридах свесив ноги и махая ими\n\n- ДА!!! Боевая арена! Здесь проходят боевые сцены!\n\nОна посмотрела на кролика и сделала суровое лицо, после достала флакон и сделав пару глотков сурово сказала\n\n- Должен будешь за дверь...\n\nПосле чего посмотрела на остальных и улыбнулась\n\n- Ищите подсказки и поймите что от вас тут требуется!",243905,null],[243965,"2026-09-30T17:32:20",62,"—Должен?\nКролик недовольно смотрит на нее в ответ, а после прыжками добирается до арены.",243953,null],[243991,"2026-09-30T17:35:35",64,"—Пх. Опять искать что-то? Мм, ладно...\nО чем то задумалась на мгновение, а после, уже сняв походку наигранную, прошлась по округе трибун арены, осматривая сидения на наличие хоть чего нибудь \n—Я надеюсь мои догадки не верны..",243953,null],[244002,"2026-09-30T17:37:29",36,"- Неее!!!) Тут не надо искать ключ от комнаты)",243991,null],[244004,"2026-09-30T17:37:40",48,"Полностью спустившись с трибун Сэдрик входит в дверной проём и какое то время застывает\n\n– Какое просторное помещение. Что это?",226349,null],[244008,"2026-09-30T17:38:14",36,"Шут повернув голову на бок показала пальцем на барда",244004,null],[244031,"2026-09-30T17:41:14",48,"Обратил капюшончик на Вельдьен и заметив что та собралась что-то искать пошел в её сторону\n\n– Хм..",226349,null],[244045,"2026-09-30T17:43:46",64,"—это ли не кошмар?\nостанавливается, а после перескакивает вниз к арене, и садится на бортики, смотря в ворота, то на кроля, то на ворота. Потом, чуть наигранно обиженно сказала\n—Не уж то опять бить нас будут? А я при параде..",244002,null],[244084,"2026-09-30T17:50:03",48,"Сэдрик, который только дошёл до дамы и уже собирался что-то передать, пронаблюдал как та почти перед ним совершила внезапный прыжок к арене. Пару секунд постоял, поглядел на неё так будто та его с двумя детьми оставила, хотя этого и не видно, потом все же удосужился подойти. \n\n– Пред тем, как возможно мы начнем драть кожу врагам нашим, я бы хотел чтобы вы посмотрели на эту интересную вещь..\n\nОн достает прямо перед ней из капюшона фотографию Шутихи, которая лыбилась светящейся запиской.",244045,null],[244086,"2026-09-30T17:50:23",36,"- Неее, слишком большого вы о себе мнения, если считаете что переживете. Хех)\n\nНадсмехается слегка над вами шут",244045,null],[244107,"2026-09-30T17:53:31",64,"—М?\nВельдьен поворачивается медленно назад в пол оборота, и, чуть виляя хвостиком, смотрит на записку, внимательно вчитываясь, наклонив голову \n—Увлекательно, но.. Скучно.",244084,null],[244125,"2026-09-30T17:58:27",64,"—ох, ты права. Придётся нас выпускать\nВельдьен грациозно, но резко, сползает вниз к арене и прогуливается медленным шагом, потягивая суставы и разминаясь, как бы готовясь к чему то. Она достаёт флейту и распевается, стуча ногами и виляя хвостом в ритм короткой, едва ли полминутной мелодии \n—Это вроде испытания?",244086,null],[244136,"2026-09-30T18:03:48",48,"Капюшончик возвращает фотографию туда откуда взял, начав блудить вокруг арены. Пока блудил, вспомнил про содержание записки на фотографии, встал на месте и внезапно начал ощупывать себя, чтобы понять что именно изменилось тогда, на трибунах перед первой сценой..",226349,null],[244142,"2026-09-30T18:09:56",36,"В кармане ты находишь необычной формы ключ, понимаешь что он судя по всему от первой из 4 дверей, но вы вошли и без него. Тупой кролик...",244136,null],[244143,"2026-09-30T18:10:05",36,"- Ну.... Типо того, да",244125,null],[244147,"2026-09-30T18:12:23",48,"–..зря только время потратил.\n\nВытащил записку, после чего обернул ей ключ и получившуюся трубочку сунул обратно в капюшон.\n\n– Может все таки пригодится..а может и нет. \n\nПрошептав это про себяс он продолжил блудить вокруг арены.",244142,null],[244154,"2026-09-30T18:18:50",64,"—Чтож.. Быстрее начнём - быстрее закончим\nну и стоит, держа флейту двумя руками, смиренно ожидая начала чего-то",244143,null],[244158,"2026-09-30T18:20:11",36,"//вообще я жду Колю, он смерти перса хотел",244154,null],[244165,"2026-09-30T18:23:02",48,"//а я жду Кролю. Он ахуенный",226349,null],[244167,"2026-09-30T18:23:32",64,"//и я жду, колю. Хули так долго",226349,null],[244200,"2026-09-30T18:35:08",64,"Не придёт Коля, крч какабычья//",244158,null],[244215,"2026-09-30T18:38:49",36,"// да пиздец....",244200,null],[244216,"2026-09-30T18:38:49",36,"//я могу его убить, но не хочу делать это в крысу",226349,null],[244226,"2026-09-30T18:40:19",64,"Чисто из за Коли стоим",244216,null],[244227,"2026-09-30T18:40:27",64,"//дежавю",244226,null],[244230,"2026-09-30T18:46:16",44,"// не у меня домашка .",243842,null],[244231,"2026-09-30T18:46:34",62,"Да, я бы хотел дождаться всех.",226349,null],[244238,"2026-09-30T18:52:12",64,"//а у кого",244230,null],[244239,"2026-09-30T18:52:18",48,"//Я выйду отсюда когда нибудь?!?",226349,null],[244241,"2026-09-30T18:52:28",64,"//нет это ловушка",244239,null],[244242,"2026-09-30T18:52:28",36,"//такая же хуйня",244239,null],[244243,"2026-09-30T18:53:25",64,"//пошлите кто щас есть похуй, выживаем - берём опыт тех кого не было, умираем - выходим от сюда нахуй",226349,null],[244257,"2026-09-30T18:56:02",64,"//братан вот ты кто по касте в файте будешь?",244239,null],[244261,"2026-09-30T18:56:54",48,"//Спамер мист зарядом. Просто мне больно ничего не остаётся",244257,null],[244262,"2026-09-30T18:56:56",36,"//вы должны были устроить рэп батл и танцы с суккубовс, а не вот это вот всё....",244243,null],[244264,"2026-09-30T18:57:25",48,"/нну могу еще из спаса кого-нибудь 1к4 украсть",226349,null],[244265,"2026-09-30T18:57:33",48,"//на этос мои полномочия все",226349,null],[244267,"2026-09-30T18:58:42",48,"//лох короче",244257,null],[244268,"2026-09-30T19:00:06",64,"//чётко",244262,null],[244270,"2026-09-30T19:00:19",64,"//ну дд крч",244261,null],[244271,"2026-09-30T19:00:31",64,"// @SwembA будешь танком, саппорт и дд есть",226349,null],[244273,"2026-09-30T19:00:59",48,"//дд первого уровня, жоско",226349,null],[244274,"2026-09-30T19:01:12",36,"//а я о чем?",244268,null],[244276,"2026-09-30T19:01:12",36,"//ладно, время на игру закончилось. Корите Колю, я честно хотела все довести до конца",226349,null],[244277,"2026-09-30T19:01:27",48,"//че колю?",244276,null],[244283,"2026-09-30T19:03:06",64,"//меф",244277,null],[244284,"2026-09-30T19:03:10",62,"У меня относительно много КД, думаю шансы есть.",244271,null],[244285,"2026-09-30T19:03:27",64,"//та с таким то саппортом ебать",244284,null],[244286,"2026-09-30T19:03:35",62,"Спамить буду Уклонение.",226349,null],[244287,"2026-09-30T19:03:38",48,"//убейте меня",226349,null],[244288,"2026-09-30T19:03:51",64,"//когда в следующий раз играем чтоб закончить?",244276,null],[244289,"2026-09-30T19:04:42",64,"//блять какое мерзкое действие просто, ужас",244286,null],[244290,"2026-09-30T19:04:58",64,"//типо, когда за нас все ок, когда против убивайте",244289,null],[244291,"2026-09-30T19:04:58",36,"//не ебу, завтра мб",244288,null],[244292,"2026-09-30T19:05:04",64,"//давай жб",244291,null],[244293,"2026-09-30T19:05:17",62,"Я ещё и провоцированных избегаю легко)",244290,null],[244294,"2026-09-30T19:05:17",64,"//ставь дату когда сможешь",226349,null],[244295,"2026-09-30T19:05:20",36,"//У меня в сб празднование ДР",244292,null],[244296,"2026-09-30T19:05:28",62,"А, и инициатива у меня +11",226349,null],[244297,"2026-09-30T19:05:29",64,"//чьё др",244295,null],[244298,"2026-09-30T19:05:58",48,"//бати",244297,null],[244299,"2026-09-30T19:06:10",64,"//с наступающим",226349,null],[244301,"2026-09-30T19:07:47",36,"//ты бля за кого...",244296,null],[244302,"2026-09-30T19:07:58",36,"//на монахе выбить +11 к инициативе...",226349,null],[244303,"2026-09-30T19:08:00",36,"//как?",226349,null],[244304,"2026-09-30T19:08:11",36,"//ну +5 от ловкости +5 от бдительного",226349,null],[244305,"2026-09-30T19:08:15",36,"//еще +1 откуда?",226349,null],[244311,"2026-09-30T19:10:24",62,"+4 ловкость, +5 черта, +2 от расы.",226349,null],[244313,"2026-09-30T19:11:55",36,"//а точн, кролик",244311,null],[244315,"2026-09-30T19:14:31",44,"// мой одногруппников, но у меня хуже . У меня пересдача",244238,null],[244350,"2026-09-30T19:23:25",64,"//мм а если на базе сумрачного охотника строить то как сочно будет",244311,null],[244351,"2026-09-30T19:23:34",64,"//типо +3 ладно хуйня",226349,null],[244352,"2026-09-30T19:23:39",64,"//плут дуэлянт",226349,null],[244354,"2026-09-30T19:24:08",64,"//в пятницу тогда?",244295,null],[244356,"2026-09-30T19:24:33",36,"//после 19:30",244354,null],[244359,"2026-09-30T19:25:39",64,"//поздновато как то",244356,null],[244360,"2026-09-30T19:25:47",64,"//ну хотя пятница похуй",226349,null],[244362,"2026-09-30T19:26:16",36,"//у меня просто в 16:00 ваншот",244360,null],[244363,"2026-09-30T19:26:25",36,"//в ирл",244362,null],[244365,"2026-09-30T19:27:20",64,"//э а мы",244363,null],[244367,"2026-09-30T19:27:25",64,"//ну спасибо Коля",244362,null],[246480,"2026-10-01T11:09:24",64,"// @Professor_3M653 сегодня буде?",226349,null],[246481,"2026-10-01T11:50:44",36,"//угу",246480,null],[246482,"2026-10-01T11:52:21",64,"//когда",246481,null],[246551,"2026-10-01T13:39:34",36,"//могу прям ща",246482,null],[246554,"2026-10-01T14:10:54",64,"//прям ща не могу",246551,null],[246587,"2026-10-01T15:30:58",64,"11 дней оно идёт //",226349,null],[246765,"2026-10-01T19:49:43",64,"//в 19:30 да?",244356,null],[246768,"2026-10-01T19:50:10",36,"//в пятницу",246765,null],[246776,"2026-10-01T19:52:06",64,"//да",246768,null],[246777,"2026-10-01T19:52:09",64,"//я про то же",226349,null],[249423,"2026-10-02T21:04:29",36,"У МЕНЯ ТОЛЬКО ЩАС ИНТЕРНЕТ ЗАРАБОТАЛ",226349,null],[249425,"2026-10-02T21:05:47",48,"//жесть",226349,null],[250247,"2026-10-03T15:27:54",64,"//сегодня можем закончить?",249423,null],[250465,"2026-10-03T19:52:34",64,"С 20 сентября\n\nЭто длиться уже 2 недели ±\n\n @Professor_3M653 ты либо распускай либо заканчивай",226349,null],[250546,"2026-10-03T21:17:53",64,"я понял почему цирк стоит в названии квеста //",250465,null],[250549,"2026-10-03T22:57:51",36,"//А Я ВИНОВАТА ЧТО ВЫ СОБРАТЬСЯ НЕ МОЖЕТЕ?!?!?",250465,null],[250558,"2026-10-03T23:11:15",64,"//так ты же дм, виновата 👊👊👊",250549,null],[250559,"2026-10-03T23:11:36",36,"//эээээ",250558,null],[250560,"2026-10-03T23:12:19",64,"//смотрю ты ни бе ни ме",250559,null],[250563,"2026-10-03T23:18:00",36,"//да я сегодня занята была. И я вроде всем эт сказала",250560,null],[250566,"2026-10-03T23:19:35",64,"//а я чет не в курсе, косяк выходит, исправляй компенсацией в 150 опыта",250563,null],[252599,"2026-10-04T19:17:43",62,"Я готов играть, к слову. Завтра на протяжении почти всего дня.",226349,null],[252600,"2026-10-04T19:18:01",62,"Нас исключительно Коля тормозит, как я понимаю.",226349,null],[252601,"2026-10-04T19:20:18",64,"Он ушёл уже давно",252600,null],[252602,"2026-10-04T19:20:28",64,"@Professor_3M653 вердикт какой?",226349,null],[252603,"2026-10-04T19:20:40",62,"Тогда чего мы ждём. Предлагаю доиграть.",226349,null],[252604,"2026-10-04T19:21:30",64,"Без дм?",252603,null],[252605,"2026-10-04T19:21:32",64,"Удачи",226349,null],[252606,"2026-10-04T19:21:45",62,"Хотелось бы и так)",252604,null],[252607,"2026-10-04T19:22:20",62,"@Professor_3M653, ну же, госпожа, дозвольте рабам своим доиграть этот квест несчастный.",226349,null],[252608,"2026-10-04T19:22:50",62,"Держите нас тут долгие дни, что тянутся вечность, покинуть триклятое место не давая.",226349,null],[252609,"2026-10-04T19:23:40",48,"Меня всё еще смущает мужик в начале больше чем квест на день длится уже третью неделю.",226349,null],[252610,"2026-10-04T19:23:43",64,"Ты тут навечно, смирись",252608,null],[252611,"2026-10-04T19:24:35",62,"Томимся мы в ожидании, ведь собраться не можем смертным отрядом, удручает нас это, в депрессию гоня. Желали бы мы закончить эти муки скорее, перестав бесполезный простой без дел и занятий.",252608,null],[252612,"2026-10-04T19:26:52",62,"Какую неделю в заточении уже провели, выхода не найдя? Интересное за границами упускаем, оставив позади активности всякие, да развлечения заморские. И дала ты нам этот цирк для чего о долготе не предупредив? Не ожидали мы поставы такой, но с поражением не миримся, продолжая бесчисленные мольбы.",226349,null],[252613,"2026-10-04T19:30:36",62,"@Professor_3M653, о, великий мастер, снизойди до наших грешных душ да оставь персонажей на упокой другим мастерам. Может смилуются они, даровав веселые приключения вместо извечного простоя.",226349,null],[252621,"2026-10-04T19:35:14",64,"Звони ей че",252613,null],[252622,"2026-10-04T19:46:43",62,"Щас, наберу.",226349,null],[252623,"2026-10-04T19:47:28",62,"Не берет. Скорее всего спит, или, может, нету интернета.",226349,null],[252624,"2026-10-04T19:54:53",27,"// Она зашла, пожаловалась, и снова пропала.",226349,null],[252648,"2026-10-04T20:03:52",62,"Она не прочитала мои мольбы. Как жаль.",226349,null],[253276,"2026-10-04T22:07:39",36,"//а хуле я об этом ни сном ни духом?",252601,null],[253282,"2026-10-04T22:08:31",36,"//ну вот предлагаю завтра и доиграть",252599,null],[253287,"2026-10-04T22:09:34",62,"Услышала о нас госпожа.",226349,null],[253291,"2026-10-04T22:10:08",36,"Инет решил заработать",253287,null],[253373,"2026-10-04T22:23:42",64,"//потому что забила",253276,null],[253375,"2026-10-04T22:24:11",64,"//очевидно потому что ты нас всей душой ненавидишь и желаешь мучить нас долго и ужасно медленно",226349,null],[253381,"2026-10-04T22:25:13",36,"//нэт",253375,null],[253472,"2026-10-04T22:48:29",64,"//вы блять рветесь на выходных доебенить чи шо я не выкупаю",253282,null],[253495,"2026-10-04T22:54:15",36,"//Я НЕ МОГЛА НА ВЫХОДНЫХ\nУ меня инета не было почти все выходные",253472,null],[253497,"2026-10-04T22:54:35",36,"//Я завтра приду домой с пар и смогу вам провести в спокойной обстановке",226349,null],[253498,"2026-10-04T22:54:35",64,"//нет бы приехать нам ебальник набить",253495,null],[253500,"2026-10-04T22:54:55",64,"//за день заканчиваем",253497,null],[253502,"2026-10-04T22:55:06",64,"//на 2 квеста, поехали @SwembA ты тоже",226349,null],[253538,"2026-10-04T23:07:45",62,"?",253502,null],[254267,"2026-10-05T11:56:55",64,"//Гайс у брата завтра др, я подготавливаюсь, возможно на играх меня будет очень мало, заранее извините",226349,null],[254429,"2026-10-05T14:38:41",36,"//...",254267,null],[254430,"2026-10-05T14:40:25",64,"//я жив",254429,null],[254431,"2026-10-05T14:40:28",64,"//веди нас",226349,null],[254432,"2026-10-05T14:40:49",36,"//я тоже воскресла вроде",254431,null],[254433,"2026-10-05T14:40:59",36,"//собери всех и позвони мне. Я отвечу",226349,null],[254434,"2026-10-05T14:42:08",64,"//ты же дм. А кто у нас",254433,null],[254435,"2026-10-05T14:43:02",64,"@SwembA и @lady_godzilla вроде?",226349,null],[254436,"2026-10-05T14:43:17",36,"//и?",254434,null],[254437,"2026-10-05T14:43:44",64,"//Полина из за флуда ушла\n\n@Illidayn ты тоже играешь да?",226349,null],[254438,"2026-10-05T14:44:23",36,"// @SwembA\n\nИграть?)",226349,null],[254439,"2026-10-05T14:44:38",36,"//Бля",226349,null],[254440,"2026-10-05T14:44:43",36,"//А кто играет...",226349,null],[254441,"2026-10-05T14:45:04",36,"// @SwembA \n@Illidayn \n@dethchinski",226349,null],[254442,"2026-10-05T14:45:07",36,"//во",254441,null],[254443,"2026-10-05T14:45:52",22,"Меня нет/",254435,null],[254444,"2026-10-05T14:46:07",62,"Я немного занят сейчас. Дайте пару минут.",254438,null],[254455,"2026-10-05T14:56:12",64,"@Illidayn",226349,null],[254464,"2026-10-05T15:04:32",48,"//а",254437,null],[254468,"2026-10-05T15:05:49",36,"//б",254464,null],[254472,"2026-10-05T15:07:33",48,"//я сдесь",226349,null],[254474,"2026-10-05T15:09:51",36,"// @SwembA \n@Illidayn \n@dethchinski",254472,null],[254475,"2026-10-05T15:10:21",48,"//☕️",254474,null],[254487,"2026-10-05T15:23:39",62,"Точно здесь.",254474,null],[254488,"2026-10-05T15:24:51",64,"//я пока пассивнее сижу",254474,null],[254495,"2026-10-05T15:27:12",36,"//ща",254487,null],[254521,"2026-10-05T15:37:39",36,"//аэаэаээаэаэ",226349,null],[254523,"2026-10-05T15:37:58",48,"//сломалась от актива",226349,null],[254547,"2026-10-05T15:49:55",36,"Шут весело сидит и болтает ногами, вы замечаете как в тени появляются два глаза, которые медленно приближаются к уху шута и что-то тихо говорят. Она загадочно, но радостно улыбается\n\n- Хорошие новости!\n\nОна встает на перила балкона и радостно хлопает в ладоши и в этот же момент закрываются двери, дырка пропала.\n\n- Те кто собираются участвовать в постановке, оставайтесь на арене, остальных же прошу удалиться со сцены",244154,null],[254548,"2026-10-05T15:50:24",62,"Заготовить действие могу, да?",226349,null],[254554,"2026-10-05T15:52:44",64,"—постановке?\nВельдьен медленно отходит на край арены, почти молчит языком тела и смотрит чуть пристальнее на шута, а после на тимейтов, играя свою игру на флейте",254547,null],[254564,"2026-10-05T15:59:00",48,"Скрытое лицо Сэдрика обратило взор на шута, перестав блудить вокруг арены. \n\n– Постановка? А сценарий нам на этот раз выдадут, или снова искать скрытый смысл в магически зашифрованой бумаге?",254547,null],[254588,"2026-10-05T16:05:23",36,"- Смысл прост) Вы должны победить на этой арене вашего оппонента или... Не победить и остаться тут)\n\nОна посмотрела на кролика и злобно улыбнулась, словно что-то задумала\n\n- В общем решайте, вас трое.\n\nОна посмотрела на барда\n\n- Те кто будут на трибуне не смогут как-либо помочь, имей ввиду",254564,null],[254589,"2026-10-05T16:05:36",36,"//если заклинание, то да",254548,null],[254590,"2026-10-05T16:06:35",36,"//действие тоже, оказывается",254589,null],[254599,"2026-10-05T16:10:44",48,"– Вы же говорили, что нам этого врага всё ровно не побороть?\n\nНаклоняет голову чуть вправо.",254588,null],[254600,"2026-10-05T16:10:58",62,"Харс начинает делать распрыжку и разминку, готовясь к бою. Заготовлю Уклонение на бросок инициативы.",254590,null],[254603,"2026-10-05T16:12:37",48,"Обернувшись на звуки спортивной зайчатины, он опускает взгляд на пол арены, застывает на месте размышляя, а после, не дожидаясь ответа, молча запрыгивает в одно пространство с мастером Харсом.",226349,null],[254604,"2026-10-05T16:12:57",36,"- Я имела ввиду убивать, а в нокаут отправить, почему бы и не попробовать?",254599,null],[254605,"2026-10-05T16:13:38",48,"Скрепляет замком ладони рук под кожаными перчатками за спиной\n– Справедливо.",254604,null],[254614,"2026-10-05T16:15:46",64,"—ну.. Проигрывать так вместе\nВельдьен делает уверенный шаг к своим виляя хвостом и наклонив голову, пока играет незамысловатую мелодию",254588,null],[254621,"2026-10-05T16:17:17",48,"– Ваш боевой дух удручает, госпожа Вельдьен, удручает.\n\nОставив одну руку за спиной, выставляет перед своим лицом кулак с выставленными вверх указательным и средним пальцами, отходя к краю арены. Заготовленный заговор Элдрич бласт на инициативу.",226349,null],[254628,"2026-10-05T16:18:02",48,"Он это говорит с ноткой иронии но как всегда абсолютно безчувственно.",254621,null],[254644,"2026-10-05T16:22:08",64,"—Ох вы правы.. Я не думаю что мы сможем победить.. Хах..\nВ ее голосе звучит некая шутливая, но ленивая манера. Заготовленное действие уклонение на бросок инициативы, хули мне",254621,null],[254653,"2026-10-05T16:25:07",62,"—Какой слабый боевой..ух...дух! Будьте сильнее и морально, и физически!\nХарс продолжает готовиться, избивая воздух лапами.",254644,null],[254660,"2026-10-05T16:26:32",64,"—с воздухом осторожнее, милый.. Не поранься *лёгкий смешок*",254653,null],[254666,"2026-10-05T16:27:19",48,"– Хех..\n\nОпускает взгляд немного ниже, усмехнувшись про себя",226349,null],[254669,"2026-10-05T16:27:52",64,"@Professor_3M653 и где",226349,null],[254671,"2026-10-05T16:28:01",36,"- Чтож... Тогда прошу представить вашему взору нашу арену еще раз)\n\nСвет с трибун гаснет а вокруг арены зажигаются жаровни и арену окутывает резкий запах гари и крови.\n\n- Перед началом вам даётся возможность встать туда куда вы захотите)",226349,null],[254672,"2026-10-05T16:28:06",48,"//10 минут",226349,null],[254673,"2026-10-05T16:28:12",48,"//сорян но 10 минут",226349,null],[254676,"2026-10-05T16:28:27",36,"//....\nЛадн, ждём-с",254673,null],[254681,"2026-10-05T16:29:32",64,"Сюда",254671,null],[254685,"2026-10-05T16:30:09",62,"—Ну что там боже? Я – Харс, сильнейший боец чащи, великий кролик и просто отличный воин леса, вы думаете я испугаюсь!? Да что бы я и испугался? Я не оставлю вам и шанса в своей скорости!\nХарс выглядит и правда быстрым. Излишне быстрым. Он за пару секунд проскочил в центр арены, делая распрыжку.",254671,null],[254686,"2026-10-05T16:30:21",62,"Ровно в центр.",226349,null],[254760,"2026-10-05T16:47:30",48,"//бем",226349,null],[254769,"2026-10-05T16:50:02",48,"//сюда",254671,null],[254829,"2026-10-05T17:01:49",36,"//так... Отлично",226349,null],[254843,"2026-10-05T17:03:33",36,"//накосячила опять....",254841,null],[254845,"2026-10-05T17:03:48",36,"//Ну ладн, вы точн знаете свое местоположение",226349,null],[254847,"2026-10-05T17:04:08",64,"Доктор оно опять началось //",254841,null],[254874,"2026-10-05T17:09:06",36,"- Отлично! Теперь когда вы все встали по местам можно начинать\n\nОна хлопает в ладоши и напротив вас лестницы стали с грохотом медленно раздвигаться в стороны открывая проход. Там было темно, но вы видели огонь, в виде лезвия\n\nВскоре это НЕЧТО вышло на арену и шут громко объявил\n\n- На арену вышел огненный палач! Против него выступает трупа из, жареной крольчатины, адского гонщика И горячей штучки!\n\nПрозвенел гонг и мечник поднял меч, напротив себя, а после взмахнул им в сторону показывая что он рад вас приветствовать, но вы его враги и всё\n\nЕсли присмотреться то можно заметить что за пределами арены что то искажалось, видимо был установлен магический купол, чтобы никто не убежал а зрители не пострадали",254841,null],[254875,"2026-10-05T17:10:12",62,"—Огонь? Слишком жалкая стихия, ветер от моих ударов просто потушит его!\nХарс подзывает палача к себе, провоцируя на битву.",226349,null],[254877,"2026-10-05T17:10:33",36,"//он вот тут",254671,null],[254878,"2026-10-05T17:10:46",36,"//кидайте инициативы",254874,null],[254879,"2026-10-05T17:10:50",64,"Вельдьен наиграно хлопает в ладоши и очень нереалистично удивляется \n—О нет, нам конец..",254874,null],[254880,"2026-10-05T17:11:05",64,"/roll@roll_bot 1d20+3 не помню сколько у меня но уклонение",254878,null],[254882,"2026-10-05T17:11:15",62,"/r +11 и уклонение",254878,null],[254886,"2026-10-05T17:12:02",48,"Сэдрик наблюдает за сей фигурой, подмечая пиромантичный вид их скорого соперника. В его пальцах уже образуется мелкий шар черной магии..\n\n– Нус..начнём",254874,null],[254887,"2026-10-05T17:12:25",48,"/r +2 инициатива",226349,null],[254889,"2026-10-05T17:12:41",62,"Харс явно был заранее готов к битве – разогретые мышцы были наполнены новой кровью, дыхание отлично выстроилось, а его лицо так и выказывало надменность.",226349,null],[254890,"2026-10-05T17:12:45",64,"А атака 🌟//",254887,null],[254891,"2026-10-05T17:12:47",48,"И сразу элдрич бласт заготовленный по инициативе черным лучом летит в сторону врага",226349,null],[254892,"2026-10-05T17:12:53",62,"Метагеймово можем обсудить план?",226349,null],[254893,"2026-10-05T17:13:17",48,"/r +6",226349,null],[254895,"2026-10-05T17:13:24",62,"Я думаю танцевать перед ним на уклонении, в случае чего уходя без провоцированной.",226349,null],[254896,"2026-10-05T17:13:24",48,"/r 1d10",226349,null],[254898,"2026-10-05T17:13:27",64,"//ты танкуешь, мрак дамажит, а я для красоты",254892,null],[254899,"2026-10-05T17:14:12",48,"//если что тоже послужишь живым щитом 😏😚",254898,null],[254900,"2026-10-05T17:14:54",64,"//если что я саппорт 🙄",254899,null],[254901,"2026-10-05T17:15:16",48,"//на кой тогда так близко стоишь. Хотя бы футов на 10 подальше😭",254900,null],[254902,"2026-10-05T17:15:23",48,"//ладно, погнали",226349,null],[254903,"2026-10-05T17:16:04",36,"- Мгх...\n\nСлышите вы приглушённо из под маски бойца пока он выгибает голову наверх, получив заряд прямо в грудь",254897,null],[254905,"2026-10-05T17:16:33",36,"/r +4",226349,null],[254907,"2026-10-05T17:17:20",64,"//в средние дистанции идти, у меня досягаемость на хилл 60 футов всего лишь",254901,null],[254908,"2026-10-05T17:17:22",62,"Музыка найдется?",226349,null],[254909,"2026-10-05T17:17:34",36,"1) Кролик @SwembA \n2) Вельдьен @dethchinski \n3) Огненный палач\n4) Сэдрик @Illidayn",226349,null],[254910,"2026-10-05T17:17:44",36,"//увы",254908,null],[254912,"2026-10-05T17:17:50",64,"Меня тут вообще в хуй не ставят я погляжу//",254909,null],[254914,"2026-10-05T17:18:03",36,"//я имя твое забываю",254912,null],[254916,"2026-10-05T17:18:13",48,"//Вельдьен",254914,null],[254917,"2026-10-05T17:18:19",64,"//запомню тебя, хз-как-её",254914,null],[254918,"2026-10-05T17:18:22",62,"Как далеко палач от меня?",254909,null],[254920,"2026-10-05T17:18:36",36,"//по карте смотри, нах она вам?",254918,null],[254921,"2026-10-05T17:18:41",36,"//.",254877,null],[254922,"2026-10-05T17:18:43",62,"Не жалуйся)",254912,null],[254924,"2026-10-05T17:18:56",64,"//35",254921,null],[254925,"2026-10-05T17:19:08",64,"@SwembA //",254924,null],[254927,"2026-10-05T17:19:13",64,"//бля чёт реально близко",226349,null],[254940,"2026-10-05T17:20:42",62,"Я подхожу на 30 футов, действием использую Уклонение и подзываю врага ближе.\n—Ну, что ты? Давай нападай!\nХод.",254877,null],[254950,"2026-10-05T17:22:23",36,"//пишите ход в конце вашего хода, и пожалуйста. Поменьше флудить",254940,null],[254963,"2026-10-05T17:24:48",64,"Вельдьен использует Диссонирующий шепот, проигрывая на \"языке нот\" с помощью флейты самые мерзкие изоощерения и прилюдии, направленные на палача. Он не поймет, но по коже пройдут муражки и отсутствие желания находиться рядом \n\n//спас мудрости от палача",226349,null],[254969,"2026-10-05T17:25:44",36,"/r +4",254963,null],[254971,"2026-10-05T17:26:16",64,"/roll@roll_bot 3д6 не прошёл и уходит прочь на всю дистанцию с помощью реакции. Кроль может провокацией ударить",226349,null],[254973,"2026-10-05T17:26:23",64,"//вот столько урона",254972,null],[254974,"2026-10-05T17:26:28",64,"Ход",226349,null],[254975,"2026-10-05T17:26:42",64,"@SwembA бьёшь? Это движение провоцирует атаки",254972,null],[254978,"2026-10-05T17:27:36",62,"Харс бьёт лапой по икре убегающего врага.",226349,null],[254979,"2026-10-05T17:27:39",62,"/r +6",226349,null],[254981,"2026-10-05T17:27:45",62,"/r d4+4",226349,null],[254989,"2026-10-05T17:28:38",36,"Ты чувствуешь жар на лапке, но видишь как враг убегает прочь от Вельдьен на 30 футов",254978,null],[254999,"2026-10-05T17:30:55",36,"После чего он злобно смотрит на Вельдьен, ведь его так нагло обманули.\n\nОн взмахивает клинком и бежит в сторону кроля, после чего бьёт его своим мечом",226349,null],[255001,"2026-10-05T17:31:01",36,"/r +6",226349,null],[255006,"2026-10-05T17:31:14",36,"/r d8+d8+4",255005,null],[255009,"2026-10-05T17:32:05",62,"С помехой",255005,null],[255011,"2026-10-05T17:32:09",36,"//ход",226349,null],[255016,"2026-10-05T17:32:40",36,"Он промахивается",255012,null],[255021,"2026-10-05T17:34:16",48,"– Отлично..Отлично..Продолжаем..\n\nБормоча про себя эти слова повторяю прикол с мистическим зарядом в глаз",226349,null],[255022,"2026-10-05T17:34:20",48,"/r +6",226349,null],[255025,"2026-10-05T17:34:46",48,"Ход",226349,null],[255030,"2026-10-05T17:35:46",62,"Харс снова использует Уклонение, продолжая попытки провоцировать палача. Он громко смеётся, отталкиваясь от его груди лапами и отходя на 30 футов в лево. Я в 40 футах от него. Ход.",226349,null],[255067,"2026-10-05T17:40:50",64,"//бля мой",226349,null],[255078,"2026-10-05T17:42:42",64,"Вельдьен испускает поток средних по силе оскорблений в палача, они, в основном, воспроизведены на языке тела и изящно говорят об 🤏 палача. Ну и она отходил за зайцегона, даруя ему",226349,null],[255079,"2026-10-05T17:42:44",64,"Спас мудрости",226349,null],[255081,"2026-10-05T17:42:48",64,"Вдохновение",226349,null],[255083,"2026-10-05T17:43:19",36,"/r +6",255079,null],[255086,"2026-10-05T17:43:57",64,"/roll@roll_bot 1д4 урона как его достоинства",255084,null],[255090,"2026-10-05T17:44:37",64,"—зайка.. Он слишком увлечён собой, бей\nследующий бросок атаки палач совершит с помехой",226349,null],[255091,"2026-10-05T17:44:43",64,"Ход",226349,null],[255109,"2026-10-05T17:47:35",64,"Вот тут я",255105,null],[255112,"2026-10-05T17:48:08",36,"//карта актуальная",255109,null],[255185,"2026-10-05T18:00:34",64,"А дм ходит?",255112,null],[255202,"2026-10-05T18:04:32",36,"//а... Ща мой ход... А я мрака жду",255185,null],[255206,"2026-10-05T18:04:58",48,"//бро ☕️",226349,null],[255218,"2026-10-05T18:08:43",64,"//дм года",255202,null],[255221,"2026-10-05T18:12:44",62,"И пропала..",226349,null],[255229,"2026-10-05T18:21:53",62,"@Professor_3M653, госпожа - хозяйка, доведите уж.",226349,null],[255233,"2026-10-05T18:23:04",31,"А вы что, хотите закончить?) нет, так не интересно. Вы вечные пленники тут. В этом и есть тайный смысл квеста)/",226349,null],[255234,"2026-10-05T18:23:22",64,"//умц",226349,null],[255253,"2026-10-05T18:28:48",62,"Вдруг госпожа д-к передумает и выпустит рабов своих, и даст она нам опыта в отпуск и денег немного, и мольбы услышаны наши будут, коль мы – слуги госпожи, дождемся и доиграем сей бой.",255233,null],[255256,"2026-10-05T18:29:43",31,"Так и создаются культы. Истово верящие молятся, но ничего не получают. Только имущество на лидера культа переписывают",255253,null],[255259,"2026-10-05T18:30:39",62,"Культ госпожи д-к будет вечен, и продлится эта вечность до момента пока не покинем мы сей цирк.",226349,null],[255285,"2026-10-05T18:37:48",64,"//безбожно",255259,null],[255286,"2026-10-05T18:38:44",62,"Это 2 раз за день, когда меня называют безбожником. Ну и пидорасом в придачу.",255285,null],[255288,"2026-10-05T18:39:21",64,"//это не моя работа",255286,null],[255301,"2026-10-05T18:48:03",36,"//инет сдох",255221,null],[255303,"2026-10-05T18:49:20",31,"Что у тебя с интернетом? Ты на луне что ли живешь?",255301,null],[255305,"2026-10-05T18:49:31",36,"//в рое бпла",255303,null],[255330,"2026-10-05T19:07:04",36,"Палач подходит к кролику и взмахом меча атакует его по жопе",255112,null],[255331,"2026-10-05T19:07:26",36,"/r -d20+6",226349,null],[255336,"2026-10-05T19:08:10",36,"/r d8+4+d6",226349,null],[255337,"2026-10-05T19:08:10",36,"/r d8+4",226349,null],[255341,"2026-10-05T19:08:37",36,"Поджарив кролика он отходит от него не провоцируя атак в сторону вельдьен на 10 футов",226349,null],[255354,"2026-10-05T19:11:09",62,"Я умер, если что. С концами.",226349,null],[255358,"2026-10-05T19:11:51",62,"Спасибо за игру.",226349,null],[255361,"2026-10-05T19:12:27",48,"Лико Сэдрика дергается от молниеносного вырубания кролика. Он отходит влево на 30 футов и проводит очередную атаку мист. зарядом по палачу",226349,null],[255364,"2026-10-05T19:12:45",48,"/r +6\n/r 1d10",226349,null],[255368,"2026-10-05T19:12:53",48,"//пизда\n\nХод",226349,null],[255413,"2026-10-05T19:38:01",64,"//по кролику бы тоже но он решил иначе",226349,null],[255414,"2026-10-05T19:38:19",64,"лечащее слово на кроя злая насмешка на врага",226349,null],[255420,"2026-10-05T19:38:36",62,"Я моментально умер.",255414,null],[255421,"2026-10-05T19:38:48",64,"//ладно не",255414,null],[255422,"2026-10-05T19:39:34",64,"//на сколько моментально?",255420,null],[255423,"2026-10-05T19:39:46",64,"//типо ниже максимума дважды хп?",226349,null],[255424,"2026-10-05T19:40:21",64,"//-12, надо -20. Могу поднять",226349,null],[255426,"2026-10-05T19:40:27",64,"//вроде",226349,null],[255431,"2026-10-05T19:41:16",62,"Я получил 22 урона. Это превышает 19 возможных хитов, что я могу утерять не умерев моментально.",226349,null],[255444,"2026-10-05T19:44:21",64,"//10",226349,null],[255446,"2026-10-05T19:44:40",64,"//10-22=-12. Ещё 8 урона надо, щас он без сознания с 0 хитами",226349,null],[255452,"2026-10-05T19:45:34",64,"//ладно похуй на это",226349,null],[255454,"2026-10-05T19:45:38",64,"//будем бегать просто",226349,null],[255460,"2026-10-05T19:46:15",64,"Перебрасывай",226349,null],[255462,"2026-10-05T19:46:28",64,"Сука",226349,null],[255463,"2026-10-05T19:46:29",64,"Везунчик",226349,null],[255464,"2026-10-05T19:46:36",64,"Додеп",226349,null],[255465,"2026-10-05T19:46:58",64,"приемущество летит колдуну",226349,null],[255466,"2026-10-05T19:48:09",64,"Не могу облом",255463,null],[255468,"2026-10-05T19:48:16",64,"//оно не так работает",255466,null],[255470,"2026-10-05T19:48:25",64,"/roll@roll_bot 3д6:2",226349,null],[255472,"2026-10-05T19:48:30",64,"3 урона",226349,null],[255474,"2026-10-05T19:48:59",64,"и отхожу на 30 футов \n—ну.. Переживём",226349,null],[255475,"2026-10-05T19:49:17",64,"в противоположном от палача направлении",226349,null],[255476,"2026-10-05T19:49:20",64,"//ход",226349,null],[255477,"2026-10-05T19:49:26",36,"// @Illidayn \n@dethchinski \nОтметьте свое положение на карте",255474,null],[255478,"2026-10-05T19:49:45",64,"//в 40 футах от палача меня поставь где нибудь",255477,null],[255479,"2026-10-05T19:49:49",62,"???",255477,null],[255480,"2026-10-05T19:50:01",64,"//ты теперь ревенант",255479,null],[255481,"2026-10-05T19:50:12",64,"//ты так просто не уйдёшь",255480,null],[255482,"2026-10-05T19:50:18",36,"Палач тут",254671,null],[255483,"2026-10-05T19:50:30",62,"Моя позиция не менялась.",255105,null],[255497,"2026-10-05T19:52:32",48,"В 30 футах налево. Тобишь..",255477,null],[255499,"2026-10-05T19:53:11",48,"Сюды",255112,null],[255510,"2026-10-05T19:57:58",36,"Палач подходит к Вельдьен и разрезает её одежду вдоль швов царапая ранами кожу и подпаливая одёжу",226349,null],[255512,"2026-10-05T19:58:02",36,"/r +7",226349,null],[255514,"2026-10-05T19:58:07",36,"23",255513,null],[255515,"2026-10-05T19:58:11",64,"Везунчик",255513,null],[255516,"2026-10-05T19:58:17",36,"/r +6",226349,null],[255518,"2026-10-05T19:58:18",64,"И у него 40 скорости?",226349,null],[255520,"2026-10-05T19:58:44",64,"Попадание круто",255517,null],[255521,"2026-10-05T19:59:06",64,"Умираем все",226349,null],[255522,"2026-10-05T19:59:24",36,"Спас ловкости можешь добавить д8",255521,null],[255523,"2026-10-05T19:59:34",64,"/roll@roll_bot 1d20+5+д8",255522,null],[255525,"2026-10-05T19:59:43",64,"По моему нормально",226349,null],[255526,"2026-10-05T19:59:44",36,"Ты чувствуешь чей-то сладкий шепот с балкона",255522,null],[255527,"2026-10-05T19:59:51",36,"/r 2d6",255524,null],[255529,"2026-10-05T19:59:58",36,"1 огнём",255528,null],[255530,"2026-10-05T20:00:09",64,"Это с сопротивлением?",255529,null],[255531,"2026-10-05T20:00:10",36,"/r d8+4+d4",255517,null],[255533,"2026-10-05T20:00:19",64,"Живём пока что",255532,null],[255534,"2026-10-05T20:00:21",36,"//у тя сопра??? Ну тогда да",255530,null],[255535,"2026-10-05T20:00:32",36,"8 урона",255532,null],[255537,"2026-10-05T20:01:05",48,"//тифлинг -.-",255534,null],[255538,"2026-10-05T20:01:12",64,"//круто",255535,null],[255541,"2026-10-05T20:02:12",64,"на сколько палач выглядит раненым?",226349,null],[255543,"2026-10-05T20:03:14",48,"В свой ход кастую Расщепление разума на палача чтобы жизнь малиной не казалась \nБонуской кастую Поспешное отступление на себя(не на кого больше) и рывком удаляюсь нахер. То бишь в течении 10ти минут у меня бонуской рывок.",226349,null],[255544,"2026-10-05T20:03:29",48,"По расщеплению спасбросок интеллекта",255543,null],[255546,"2026-10-05T20:03:42",64,"//может внушением ему?",226349,null],[255549,"2026-10-05T20:04:35",48,"- ячейка за отступление",255543,null],[255558,"2026-10-05T20:07:09",64,"@Professor_3M653",226349,null],[255562,"2026-10-05T20:10:03",48,"Сюда убегаю",255509,null],[255565,"2026-10-05T20:10:49",64,"Я в свой ход кастую туманный шаг и иду вон туда вон, ну и основным действием насмешка",255509,null],[255566,"2026-10-05T20:11:02",64,"@Professor_3M653 с тебя спасы мудрости и интеллекта",226349,null],[255569,"2026-10-05T20:12:20",48,"Сначала интеллекта. И при провале интеллекта -1к4 к следующему спасу и...",255566,null],[255570,"2026-10-05T20:12:56",48,"/r 1d6",255569,null],[255572,"2026-10-05T20:12:58",48,"И получит столько психического урона. При успехе ничего",226349,null],[255573,"2026-10-05T20:13:08",64,"/r 1d4",226349,null],[255575,"2026-10-05T20:13:25",64,"И при провале атака с помехой следующая",226349,null],[255579,"2026-10-05T20:18:46",36,"А сам как думаешь? Он в балахоне, там не видно",255541,null],[255581,"2026-10-05T20:19:53",64,"//Вельдьен профессионально читает язык тела и лица. Если со вторым понятно, то по движениям и общему запасу энергии во время действий можно понять хоть что то",255579,null],[255583,"2026-10-05T20:20:45",36,"//бонуску потратишь на эт",255581,null],[255584,"2026-10-05T20:21:22",64,"//ладно не надо",255583,null],[255585,"2026-10-05T20:21:48",36,"/r",255569,null],[255587,"2026-10-05T20:22:12",36,"/r +6",255566,null],[255594,"2026-10-05T20:23:56",64,"Ход",255565,null],[255620,"2026-10-05T20:30:53",36,"//вот и чо там было?...",226349,null],[255622,"2026-10-05T20:31:43",48,"Я убежал, вот че было",255562,null],[255623,"2026-10-05T20:31:45",64,"@Illidayn твой",226349,null],[255624,"2026-10-05T20:31:53",48,"//та я думаю",226349,null],[255625,"2026-10-05T20:32:02",36,"//я кста исправила эту ошибку и уменьшила взамен ему хиты. Так что не надо буянить",255620,null],[255626,"2026-10-05T20:33:03",48,"Так, нуу.. можно итоговую карту а то путаюсь",226349,null],[255629,"2026-10-05T20:37:20",48,"//помоему так",226349,null],[255631,"2026-10-05T20:38:19",48,"//ну я клеткой выше не суть",255629,null],[255632,"2026-10-05T20:38:25",64,"Да да кидай уже",255629,null],[255634,"2026-10-05T20:39:45",48,"Короче подхожу на 60 футов, кидаю Элдрич бласт и бонуской..уматываю на место. Прости, я тебе ничем не помогу..",226349,null],[255635,"2026-10-05T20:39:50",48,"/r +6",226349,null],[255639,"2026-10-05T20:40:56",64,"У тебя приемущество от остроты и вдохновение вроде бы",255634,null],[255640,"2026-10-05T20:41:12",48,"Ага..",255639,null],[255642,"2026-10-05T20:41:24",48,"Вдохновение оставлю",226349,null],[255643,"2026-10-05T20:41:28",48,"/r d10",226349,null],[255645,"2026-10-05T20:42:01",48,"Прощай, крошка..не будет у нас минирогатых с ноткой теневого плана//",226349,null],[255647,"2026-10-05T20:43:35",64,"//если я умираю а ты живёшь, то отдай латы поломанные Дуври по братске",255645,null],[255648,"2026-10-05T20:43:45",48,"//базар",255647,null],[255649,"2026-10-05T20:44:48",64,"ну а в свой ход я использую \"мантию вдохновения\", а после раскаленный металл на меч палача. Я и Сэдрик получаем 5 временных хитов, он может отойти на 30 футов не провоцируя атак немедленно",226349,null],[255650,"2026-10-05T20:44:53",64,"/roll@roll_bot 2д8",226349,null],[255652,"2026-10-05T20:45:48",64,"@Professor_3M653  14 урона огнём и он должен бросить меч или получит помеху на все атаки и проверки характеристики",226349,null],[255653,"2026-10-05T20:45:48",36,"//огнем?",255651,null],[255654,"2026-10-05T20:45:55",64,"Или",255652,null],[255655,"2026-10-05T20:46:25",64,"Там спас тела или он бросает предмет",226349,null],[255656,"2026-10-05T20:46:29",64,"@Professor_3M653 тело кинь",226349,null],[255657,"2026-10-05T20:46:47",36,"/r +4+d8",255656,null],[255659,"2026-10-05T20:46:57",36,"/r d20+4+d8",226349,null],[255661,"2026-10-05T20:47:01",64,"искусная острота",226349,null],[255662,"2026-10-05T20:47:02",48,"Сюда убегаю \"немедленно\"",255629,null],[255664,"2026-10-05T20:47:11",64,"Спасибо помогло",226349,null],[255665,"2026-10-05T20:47:14",64,"Бьёт с помехой",226349,null],[255666,"2026-10-05T20:47:44",64,"приемущество Сэдрику",226349,null],[255668,"2026-10-05T20:49:07",36,"- РГХ! Мой меч... Он горит! Не просто, а огнём... Боль от жара... Мне нравится!!!\n\nОн смотрит на тебя и ты видишь его безумный взгляд\n\n- Теперь начинается настоящее представление!\n\nЕго ноги обвились пламенем и он совершает два удара по Вельдьен",226349,null],[255669,"2026-10-05T20:49:12",36,"/r +6",226349,null],[255672,"2026-10-05T20:49:16",64,"Помеха там",255670,null],[255673,"2026-10-05T20:49:20",64,"Бля иди нахуй",255671,null],[255674,"2026-10-05T20:49:25",64,"Везунчик",226349,null],[255676,"2026-10-05T20:49:30",64,"Перекидывай -д20+6",226349,null],[255677,"2026-10-05T20:49:45",36,"//не, там просто доп бросок",255676,null],[255678,"2026-10-05T20:49:58",64,"Там переброс, он бросает с помехой",255677,null],[255679,"2026-10-05T20:49:59",48,"//кубы такие твари",226349,null],[255680,"2026-10-05T20:50:14",36,"//ну, раз с помехой кинул, потом еще раз",255678,null],[255681,"2026-10-05T20:50:20",36,"Эт с помехой",255671,null],[255682,"2026-10-05T20:50:25",36,"И это",255675,null],[255684,"2026-10-05T20:50:27",36,"Одна атака",226349,null],[255686,"2026-10-05T20:50:32",36,"Это уже вторая",255683,null],[255692,"2026-10-05T20:51:23",64,"11 хп",226349,null],[255694,"2026-10-05T20:51:37",64,"Даже 14",226349,null],[255707,"2026-10-05T20:54:42",36,"Он перемещается от тебя на 15 футов без провоцирования в сторону колдуна, а после еще на 40 футов к нему",226349,null],[255708,"2026-10-05T20:54:52",36,"//актуальна карта",254671,null],[255711,"2026-10-05T20:55:14",64,"//живём",255707,null],[255713,"2026-10-05T20:55:50",48,"Расщепление разума\nСпасбросок интеллекта",255708,null],[255714,"2026-10-05T20:57:27",48,"//зато поджигать флуд так ты в здравии и бодроствовании",226349,null],[255715,"2026-10-05T20:57:40",64,"@Professor_3M653",255713,null],[255716,"2026-10-05T20:57:46",48,"//жесть её инет воротит",226349,null],[255717,"2026-10-05T21:02:25",64,"С помехой от раскаленного металла",255713,null],[255718,"2026-10-05T21:02:26",64,"Кстати",226349,null],[255730,"2026-10-05T21:31:11",36,"/r -",255713,null],[255733,"2026-10-05T21:31:29",48,"//ёб твою мать",255731,null],[255734,"2026-10-05T21:31:41",36,"//все? Или еще что?",255733,null],[255735,"2026-10-05T21:31:58",64,"Пупупу",255731,null],[255736,"2026-10-05T21:32:05",48,"Реакции Вельдьен нет так что..",226349,null],[255737,"2026-10-05T21:32:44",64,"А я даже смысла не вижу",255736,null],[255739,"2026-10-05T21:33:41",48,"Убегаю сюда обходя мужичка\nХод",255708,null],[255741,"2026-10-05T21:34:09",36,"//траекторию бега пожалуйста",255739,null],[255744,"2026-10-05T21:35:04",48,"//с учетом рывка за бонуску",255739,null],[255746,"2026-10-05T21:35:17",48,"Ход",226349,null],[255749,"2026-10-05T21:36:01",64,"Бонусным продливаю действие раскаленного металла",226349,null],[255750,"2026-10-05T21:36:04",64,"/roll@roll_bot 2д8",226349,null],[255752,"2026-10-05T21:36:12",64,"@Illidayn спас тела или роняет оружие",226349,null],[255758,"2026-10-05T21:36:30",64,"@Professor_3M653",255752,null],[255760,"2026-10-05T21:36:38",64,"С помехой",255752,null],[255768,"2026-10-05T21:39:18",64,"Давай ему ещё легендарные действия дай //",226349,null],[255769,"2026-10-05T21:39:29",64,"//мало нам боли",226349,null],[255776,"2026-10-05T21:40:41",64,"//вы блять умные альтернативно или что?",226349,null],[255777,"2026-10-05T21:40:47",64,"//почему вы не взяли 3?",226349,null],[255778,"2026-10-05T21:40:59",64,"//ты типо просто бесплатно стал сильнее",255777,null],[255790,"2026-10-05T21:44:09",64,"// @SwembA а ты как вообще 1 уровня оказался?",226349,null],[255791,"2026-10-05T21:44:25",64,"//ты же монах, сильно зависящий от уровня класс",226349,null],[255792,"2026-10-05T21:45:04",36,"Он не отпускает оружие, оно прожигает ему руку. Он обхватывает клинок и прижав его к груди падает всем тело на него\n\nОгонь с жаровен гаснет, а после включается свет\n\nВы слышите как шут радостно вам хлопает\n\n- Браво! Браво!!! Это было впечатляюще!\n\nВы видите как металлические решётки поднимаются и оттуда выходят еще две личности, но вы не можете понять кто это, какая-то магия мешает внятно определить их облик. Они хватают палача за плечи и утаскивают вглубь комнат арены, за ними с скрежетом закрывается решётка\n\nВельдьен замечает еле еле горящий клинок на арене, на его рукояти все еще можно было заметить приженную плоть палача\n\n- Поздравляю, вы хорошо выступили на этой постановке!\n\nВы слышите из пустых мест аплодисменты, что словно в загрузкой появились не сразу. Ведь уже даже тело унесли...\n\nМагический купол судя по всему пропал, а шут спрыгнув с балкона подошла к вам и вручила по тикету со знаком цирка\n\n- Вот... Покажете перед выходом и вам выдадут особую награду)\n\nОна мило улыбается держа свою трость за спиной ожидая реакции",255752,null],[255803,"2026-10-05T21:46:21",36,"//отказался от аппа",255790,null],[255806,"2026-10-05T21:47:08",64,"Вельдьен смотрит на все это уставше и без эмоций, она берет то, что даёт ей шут и волшебной рукой подбирает меч\n—...мы свободны?\nее интонация и лицо показывает сильную усталость, и лишь уставшая улыбка показывает её облегчение перед этим",255792,null],[255808,"2026-10-05T21:47:49",36,"- А что? Вам не понравилось наше представление? Вы уже хотите нас покинуть? А как же другие выступления? Они ждут своих актёров",255806,null],[255809,"2026-10-05T21:49:02",48,"Подбежав к Вельдьен, Сэдрик уже собирался в очередной раз опалить противника заклинанием..но тут эта картина. Он, прослужав слова Шутихи, опускает голову. Из под капющона веет холодом..напраженной переработки того что сейчас произошло.\n\n– Никогда..еще никогда я так не выкладывался..никогда..а все из-за какого то цирка..смешно..",226349,null],[255810,"2026-10-05T21:50:18",48,"Потом он обернул взгляд на убитого кролика.\n\n– А с ним что..?",226349,null],[255811,"2026-10-05T21:50:20",64,"—Нам?\nна пару секунд замирает и уставше смотрит на тело кролика, после переводит взгляд назад на неё, хвост Вельдьен окутывает ее ногу \n—Нет-нет.. Что вы? Очень понравилось. Но ты посмотри на нас: как труппа из двух, дорогая?",255808,null],[255815,"2026-10-05T21:56:38",36,"- Тоже верно... Тогда предлагаю пройти...\n\nОна посмотрела на нежить с капюшоном\n\nОна смотрела на тебя холодным взглядом, настолько словно, ты вновь оказался на том свете\n\nОна достала из-за спины кувшин и вы наконец увидели магические руны. Это был бесконечный кувшин с кофе.\n\nОна сделала оттуда пару глотков и убрав его вновь улыбнулась\n\n- Ой, не переживайте вы так за него... У нас есть те кто могут позаботиться о хрустящем поджаренном кролике)\n\nПосле чего она обхватила Вельдьен за плечо и рассказывая со смехом шутовые сцены и фокусы с картами повела их на выход из арены\n\nДвери перед вами сами открылись, когда вы выходили свет медленно гас, последнее освященное место был тот самый зажаристый кролик. После чего и этот последний лучик потух, а дверь с тяжелым грохотом закрылась\n\nШут повела вас в сторону выхода.\n\nВы заметили что выход закрыт на ключ, который был у шута, а справа от вас был ларек с подарками.\n\n- Тут что-то типо казино, отдаёте талончик, крутите барабан и забираете выпавший приз)",255811,null],[255824,"2026-10-05T22:00:27",48,"– Тц..как \"увлекательно\". \n\nОн говорил спокойно, но с ноткой издевки, и из под капюшона всё равно веяло напряжением после битвы. К тому же он пытался ходить медленно, ибо не хватало тому времени отдышаться и впоследствии развеять заклинание. Он ждёт пока Вельдьен первой подойдет к этому аппарату.",255815,null],[255826,"2026-10-05T22:01:56",64,"Слыша речи шута, Вельдьен явно не слушала суть, и изредка соглашалась и кивала с тяжёлой улыбкой и уставше наклоненной головой\n—Ох, щедрое веселье. Весьма заманчиво. \nГлубоко вдохнула, хлопнула в ладоши с лёгкой улыбкой краем рта, а после подошла, наигранно виляющей и счастливой походкой к ларьку, её хвост совсем совсем не двигался, лишь загнулся витком. Подходя она посмотрела, куда можно протянуть талончик",255815,null],[255827,"2026-10-05T22:02:52",36,"Ты увидела язык похожий на змеиный что вылезал, словно ожидая пока туда что-то положат\n\n//после кидай д6",255826,null],[255828,"2026-10-05T22:05:37",64,"—..мм\nна пару секунд Вельдьен непроизвольно тоже языком змеиным выебнулась, как у змей, но тут без цели. После она достала билет и, едва виляя хвостом у основания от ожидания награды, сунула билет",255827,null],[255829,"2026-10-05T22:05:40",64,"/roll@roll_bot д6",226349,null],[255831,"2026-10-05T22:08:31",36,"Язык слизал твой билет в себя, а после ты услышала стуки шестерёнок. Звон печки. Маленькие колокольчики, звук мерцания магии. А после рот, откуда вытаскивался язык открылся и ты увидела маленький бархатный мешочек",255830,null],[255832,"2026-10-05T22:11:50",48,"Сэдрик лишь смотрел с незаметным интересом, чуть наклонив голову вправа, и иногда переводя взгляд на Шута. В моменты разглядывания этой разодетой в красочный костюм дамы из под капюшона веяло толи презрением, толи опасением. Сэдрик сам не понимал, что конкретно думает о ней..да и в принципе по большей части ничего не понимал.",226349,null],[255833,"2026-10-05T22:13:10",36,"//потом в лс скину",255831,null],[255834,"2026-10-05T22:14:37",64,"Вельдьен с неким любопытством наблюдает за процессом, чуть наклонив голову, проявляя интерес. Ее хвост двигался активнее с каждым новым звуком, хотя и замер когда билет ушёл. После того, как награда была высталена на показ, Вельдьен замерла и несколько секунд смотрела на мешочек, прежде чем взять и осмотреть его, медленно идя в сторону выхода из цирка, ее зрачки чуть расширились а хвост двигался активнее, пока та выходила, с любопытством смотря на мелочь. На прощание с цирком, Вельдьен помахала рукой и поклонилась, в знак благодарности, хотя по ней и не скажешь, что та будет скучать \n\n//конец же?",255831,null],[255835,"2026-10-05T22:16:01",48,"//..там ворота заперты",255834,null],[255837,"2026-10-05T22:17:36",64,"//там нас обещали вывести",255835,null],[255839,"2026-10-05T22:18:15",64,"//а если опустить моменты то я спать хотел идти уже",255837,null],[255840,"2026-10-05T22:18:19",48,"Проводив взглядом Вельден и прошептав про себя на Бездне \"Еще увидимся..\", Он еще раз глянул на Шута, а потом неуверенно и медленно доковылял до ларька. \n\n– Так..сюда же?\n\nОн неуверенно глядит на это произведение исскуства, а после все таки удосуживается вставить талон на змеиный язык ..",226349,null],[255841,"2026-10-05T22:18:54",36,"Шут перед твоим уходом подошла к тебе и взяв твои руки в свои, положила туда билет на следующее посещение. Оно в этот раз было золотым. Словно награда. И мерцал словно звезды в ночном небе. После чего она закрыла его в твоих руках. Словно это твоя тайная награда и помахав рукой выпустила тебя через тяжелые бархатные кулисы закрытые на амбарный замок, который шут уже открыла. После чего она смотрела на сэдрика наблюдая за его действиями",255834,null],[255842,"2026-10-05T22:19:56",36,"Ты неуверенно положил билет на язык он всосал его в себя и стал производить такие же звуки как и у Вельдьен\n\n//кинь д6",255840,null],[255843,"2026-10-05T22:20:14",48,"/r d6",255842,null],[255845,"2026-10-05T22:20:15",64,"//у Вельдьен слизал, у Сэдрика всосал",255842,null],[255846,"2026-10-05T22:20:34",48,"//шлюхобот",226349,null],[255847,"2026-10-05T22:23:18",36,"Ты получаешь такой же бархатный мешочек что и у вельдьен.\nЗатем шут протягивает тебе билет, но более холодно. Билет такой же, золотистый и ты выходишь из цирка\n\nВыходя из шатра и обернувшись назад вы не замечаете его, вы снова оказались на пустой, старой площади. Лишь большие часы злощасно пробивают полночь",255844,null],[255848,"2026-10-05T22:23:18",36,"//конец",226349,null],[255849,"2026-10-05T22:23:19",36,"// @dethchinski \n@Illidayn \nПолучаете по 250 опыта\n\nОстальное распишу позже\n\nТак же у вас есть коробка с попкорном, да",226349,null],[255850,"2026-10-05T22:23:36",64,"//а за файт",255849,null],[255851,"2026-10-05T22:23:56",48,"//а за отыгрыш. Не, у меня отыгрыш херни, не спорю, но все таки",226349,null],[255852,"2026-10-05T22:24:06",36,"//а точ... За квест забыла\n\nСуммарно 500 опыта, с учетом файта",255850,null],[255853,"2026-10-05T22:24:16",36,"//тебе допом 150",255850,null],[255854,"2026-10-05T22:24:17",64,"//пиздец, ладно",255852,null],[255855,"2026-10-05T22:24:23",64,"//ладно не пиздец",255853,null],[255856,"2026-10-05T22:24:29",36,"//палач был 3 по",255854,null],[255857,"2026-10-05T22:24:33",48,"//допустим",255852,null],[255858,"2026-10-05T22:24:40",36,"//Чо вы хотите?",226349,null],[255859,"2026-10-05T22:24:49",48,"//свободы",226349,null],[255860,"2026-10-05T22:24:54",48,"// и мы её получили",226349,null],[255861,"2026-10-05T22:24:56",36,"//ты свободен",255859,null],[255862,"2026-10-05T22:24:59",48,"//спасибо за квест",226349,null],[255863,"2026-10-05T22:25:02",36,"//добби свободен",255859,null],[255864,"2026-10-05T22:25:08",64,"//нас двое в итоге было, по",255856,null],[255865,"2026-10-05T22:25:12",36,"//жду отчетов)",255862,null],[255866,"2026-10-05T22:25:12",64,"//ай ладно",226349,null],[255867,"2026-10-05T22:25:28",36,"Вы и получили опыт от кролика",255866,null],[255868,"2026-10-05T22:25:32",48,"//завтра, я спать хочу умираю",255865,null],[255870,"2026-10-05T22:25:41",64,"//можно лут кролика попилить?",255867,null],[255871,"2026-10-05T22:25:45",36,"//а мне отчет всю ночь писать на лабу",255868,null],[255872,"2026-10-05T22:26:04",36,"//а его скушали)",255870,null],[255873,"2026-10-05T22:26:05",36,"//он там остался",226349,null],[255874,"2026-10-05T22:26:28",64,"//точно он монах, с него нехуй взять",226349,null],[255875,"2026-10-05T22:26:41",64,"//меч тоже распиши",255873,null],[255876,"2026-10-05T22:26:43",48,"//надо было его обворовать когда была возможность",226349,null],[255884,"2026-10-05T22:27:43",48,"//хотя бы мех срезать",255874,null],[255885,"2026-10-05T22:28:00",48,"//эхх)",226349,null],[255886,"2026-10-05T22:28:16",64,"//вот у тебя квест идёт 17 дней, в итоге на двух игроков по 500 опыта. У меня квест идёт неделю, а 500 опыта 5 человек получает за 1 сцену боевую",255852,null],[255887,"2026-10-05T22:28:34",64,"//где то я проебался наверное",255886,null],[255888,"2026-10-05T22:30:31",36,"//у меня планировался он длиннее и на неделю",255886,null],[255889,"2026-10-05T22:30:36",27,"// В любом случае ты получил больше опыта чем за простой, раз в два, а то и три",255886,null],[255890,"2026-10-05T22:30:37",36,"//а тут... Как вышло",226349,null],[255891,"2026-10-05T22:31:29",27,"// Плюс твой квест исключение, ибо как ты сам там отмечал, что главная награда и лут там – опыт",255886,null],[255892,"2026-10-05T22:31:35",27,"// И лут с Про",226349,null]]);
